-- ==========================================
-- Nutri-Pilot (悦小厨) Seed Data
-- Generated 250 Authentic Dishes
-- ==========================================

-- 0. SCHEMA DEFINITION -- CLEAN START
DROP TABLE IF EXISTS dish_ingredients CASCADE;
DROP TABLE IF EXISTS dishes CASCADE;
DROP TABLE IF EXISTS supplier_skus CASCADE;

DROP TYPE IF EXISTS taste_preference CASCADE;
DROP TYPE IF EXISTS diet_goal CASCADE;
DROP TYPE IF EXISTS hometown_cuisine CASCADE;
DROP TYPE IF EXISTS storage_zone CASCADE;

CREATE TYPE taste_preference AS ENUM ('light', 'spicy', 'sweet', 'salty', 'sour', 'seafood', 'veggie', 'default');
CREATE TYPE diet_goal AS ENUM ('lose_weight', 'muscle_gain', 'maintain', 'detox', 'pregnancy', 'damp_clear', 'authentic_hk');
CREATE TYPE hometown_cuisine AS ENUM ('sichuan', 'cantonese', 'jiangnan', 'northern', 'western', 'japanese_korean', 'southeast_asian');
CREATE TYPE storage_zone AS ENUM ('frozen', 'chilled', 'fresh_produce', 'pantry');

CREATE TABLE supplier_skus (
  id UUID PRIMARY KEY,
  supplier_name VARCHAR(100),
  product_name_zh VARCHAR(255),
  storage_zone storage_zone
);

CREATE TABLE dishes (
  id UUID PRIMARY KEY,
  title_zh VARCHAR(255),
  origin_cuisine hometown_cuisine,
  flavor_tags taste_preference[],
  health_benefit_tags diet_goal[],
  seasonal_tag VARCHAR(100),
  image_url VARCHAR(255),
  prep_steps_json JSONB,
  cook_steps_json JSONB
);

CREATE TABLE dish_ingredients (
  id UUID PRIMARY KEY,
  dish_id UUID REFERENCES dishes(id) ON DELETE CASCADE,
  sku_id UUID REFERENCES supplier_skus(id) ON DELETE CASCADE,
  quantity_small_household INT,
  quantity_large_household INT
);

