INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c43fffa3-9e78-4683-a27f-1cdbc8480bc9', '无油家庭版烤鱼', 'sichuan', '{light}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g的深海高蛋白鲜鱼表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 深海高蛋白鲜鱼, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 深海高蛋白鲜鱼, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的深海高蛋白鲜鱼放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将深海高蛋白鲜鱼彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的深海高蛋白鲜鱼表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e589b87e-8554-43e4-946c-26730c227003', '全麦萨拉米瘦火腿披萨', 'western', '{default}', '{detox}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备一张发好的披萨饼底（也可用低脂墨西哥卷饼代替），在其表面均匀平涂一层番茄披萨底酱。","step_en":"Prepare a pizza crust (or tortilla), spread tomato pizza sauce evenly.","step_tl":"Ihanda ang pizza crust, lagyan ng tomato sauce."},{"zone":"B","step_zh":"将主食材有机精选瘦猪肉切成均匀薄片或小块，在底盘薄薄先撒上一层马苏里拉拉丝芝士。","step_en":"Slice 有机精选瘦猪肉 thinly, sprinkle a light layer of mozzarella cheese on the base.","step_tl":"Hiwain ang 有机精选瘦猪肉, lagyan ng cheese sa ibabaw."},{"zone":"C","step_zh":"洗净四季时鲜杂蔬拼盘切小块，用厨房纸充分吸干多余水分防止塌陷；烤箱提前预热至200°C。","step_en":"Wash and dice 四季时鲜杂蔬拼盘, preheat oven to 200°C.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, i-preheat ang oven sa 200°C."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将有机精选瘦猪肉片和脱去水分的四季时鲜杂蔬拼盘块美观、均匀地铺满在披萨饼面上","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 在最上面再厚厚地撒上一层诱人的马苏里拉拉丝芝士封层","time_seconds":30},{"step_zh":"[烤箱200°C/Oven] 迅速送入预热好的烤箱中层，设置上下火200°C安全烘烤约15分钟","time_seconds":900},{"step_zh":"[常温/Room Temp] 密切观察表面芝士完全融化并呈现金黄微焦状后取出，滚刀切成扇形拉丝食用","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('38b89c76-bea9-4fff-a5b2-f516b129e01e', '低盐京酱肉丝', 'sichuan', '{salty}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('96bd66e0-585b-4445-abb9-2a86de7aea55', '高蛋白香煎嫩牛排', 'western', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g高品质原切牛肉/瘦猪颈肉表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 高品质原切牛肉/瘦猪颈肉, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 高品质原切牛肉/瘦猪颈肉, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g高品质原切牛肉/瘦猪颈肉，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在高品质原切牛肉/瘦猪颈肉表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与高品质原切牛肉/瘦猪颈肉装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('9cdd655b-a56c-4019-a307-2d942664cbe5', '鲜汤酸菜鱼', 'sichuan', '{sour}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将深海高蛋白鲜鱼洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 深海高蛋白鲜鱼, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 深海高蛋白鲜鱼, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将有机生鲜绿叶蔬菜切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 有机生鲜绿叶蔬菜 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 有机生鲜绿叶蔬菜, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的深海高蛋白鲜鱼和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的有机生鲜绿叶蔬菜块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8bad265f-13a8-487d-a49d-c3ce470d913a', '粗粮斑斓风味薄饼', 'southeast_asian', '{default}', '{detox}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('dbfb04f5-d7aa-4aba-9da2-5c010e6e922c', '粗粮野菜包子蒸制', 'jiangnan', '{default}', '{detox}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g有机生鲜绿叶蔬菜洗净切碎备用。","step_en":"Wash and chop 100g of 有机生鲜绿叶蔬菜.","step_tl":"Hugasan at tadtarin ang 100g na 有机生鲜绿叶蔬菜."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入有机生鲜绿叶蔬菜，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('aec188fa-f69a-4fcb-a9a3-a4bb13a6a576', '高钙滑蛋虾仁', 'cantonese', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a3df8037-72d7-4bc3-acdf-fe3394bede05', '补血黑米红枣粥', 'jiangnan', '{default}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和天然粗粮黑小麦/综合高蛋白迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('81d8f448-ffc9-4fe1-afa0-68a3b250d164', '鲜虾叻沙汤面', 'southeast_asian', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将深海白对虾/活虾切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 深海白对虾/活虾, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 深海白对虾/活虾, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的深海白对虾/活虾滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回深海白对虾/活虾煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('658e18d7-4334-40b3-a171-ef4e451a8ed3', '高蛋白清汤肉荞麦面', 'jiangnan', '{light}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将有机精选瘦猪肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 有机精选瘦猪肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的有机精选瘦猪肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回有机精选瘦猪肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('17e7ad23-40e9-477a-9c6d-f742bccedf7e', '全麦墨西哥鸡肉卷饼', 'western', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g农家散养清远鸡肉表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 农家散养清远鸡肉, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 农家散养清远鸡肉, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g农家散养清远鸡肉，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在农家散养清远鸡肉表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与农家散养清远鸡肉装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('da8624e2-0ba3-4ffd-b492-85ddb71161c1', '西红柿土鸡蛋打卤面', 'jiangnan', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将农家散养清远鸡肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 农家散养清远鸡肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 农家散养清远鸡肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的农家散养清远鸡肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回农家散养清远鸡肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('01343c94-6e1c-4406-8ee8-8623b2d37faf', '抗氧化天然蜂蜜烤南瓜', 'western', '{sweet}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g的天然粗粮黑小麦/综合高蛋白表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的天然粗粮黑小麦/综合高蛋白放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将天然粗粮黑小麦/综合高蛋白彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的天然粗粮黑小麦/综合高蛋白表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('cf2e7847-3d56-4bb9-99cc-ef18871c3e0e', '无糖糖醋排骨', 'sichuan', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('33d4bda3-f13d-4f1d-9d37-39c97ddd9f5e', '少油扬州杂蔬炒饭', 'cantonese', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"准备300g隔夜冷藏米饭，用3ml食用油或清水在碗中提前抓散成颗粒状防粘。","step_en":"Prepare 300g leftover rice, break into grains with a little oil or water.","step_tl":"Ihanda ang 300g na kanin, paghiwalayin ang butil."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成约1cm见方的小丁；同时将四季时鲜杂蔬拼盘洗净也切成同等大小的碎丁保持口感统一。","step_en":"Dice 天然粗粮黑小麦/综合高蛋白 into 1cm cubes; wash and completely dice 四季时鲜杂蔬拼盘.","step_tl":"Tadtarin ang 天然粗粮黑小麦/综合高蛋白 at 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"碗中打散2个鸡蛋搅匀成蛋液，并备好提香的葱花。","step_en":"Beat 2 eggs evenly, prepare chopped scallions.","step_tl":"Batihin ang 2 itlog, ihanda ang sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧热炒锅倒入15ml食用油，倒入打散的鸡蛋液，快速炒熟盛出并略微切碎后备用","time_seconds":60},{"step_zh":"[中火/Medium Heat] 锅底补5ml底油，下入天然粗粮黑小麦/综合高蛋白丁煸炒至断生表面微缩，接着下入四季时鲜杂蔬拼盘丁炒出明香","time_seconds":120},{"step_zh":"[大火/High Heat] 倒入提前抓散的米饭，转大火快速持续翻炒按压，让每一粒米均匀受热","time_seconds":180},{"step_zh":"[大火/High Heat] 将炒好的鸡蛋倒回锅中，加入10ml生抽、2g盐和10g葱花，大火颠锅翻炒30秒产生锅气出炉","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2f6f37cf-2e7f-4061-9ba2-27bc0d7163a6', '高锌蒜蓉蒸扇贝', 'cantonese', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g优质海鲜干贝类，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 优质海鲜干贝类 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 优质海鲜干贝类 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g有机香辛料(提香解腻)切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 有机香辛料(提香解腻) into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 有机香辛料(提香解腻) sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有优质海鲜干贝类的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bb6f24bc-4d2c-4627-b617-40055938f740', '高汤鲜菌砂锅米线', 'jiangnan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 天然粗粮黑小麦/综合高蛋白, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 天然粗粮黑小麦/综合高蛋白, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的天然粗粮黑小麦/综合高蛋白和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('87be4243-3595-4b41-b0d0-0b252bd7ffb7', '低钠蚝油鲜捞面', 'cantonese', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a4997fcd-8008-408f-9e4f-762fa87c154c', '高蛋白白汁虾意面', 'western', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将深海白对虾/活虾切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 深海白对虾/活虾, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 深海白对虾/活虾, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的深海白对虾/活虾滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回深海白对虾/活虾煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('47c923dd-c74b-42fa-924d-43abcdf3561b', '全麦少油葱花卷', 'jiangnan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g紫皮鲜洋葱/大葱洗净切碎备用。","step_en":"Wash and chop 100g of 紫皮鲜洋葱/大葱.","step_tl":"Hugasan at tadtarin ang 100g na 紫皮鲜洋葱/大葱."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入紫皮鲜洋葱/大葱，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('51408ee8-8e3a-459a-a6c8-6256e1e10e8e', '低脂全麦简易寿司卷', 'jiangnan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6b0083ad-a54f-49ac-88e5-197a95ad1cd7', '高蛋白巴东风味肉', 'southeast_asian', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('21ab5c98-e24b-4340-b4a4-11204502656c', '无油蜜汁烤鸡腿', 'cantonese', '{sweet}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g的农家散养清远鸡肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 农家散养清远鸡肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 农家散养清远鸡肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的农家散养清远鸡肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将农家散养清远鸡肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的农家散养清远鸡肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c9efe12d-c710-4889-bf9b-4aadca366c84', '高蛋白番茄炖牛腩', 'sichuan', '{sour}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成3cm见方的块，放入800ml冷水锅中，大火烧开焯水3分钟，捞出洗净血沫。","step_en":"Cut 300g of 高品质原切牛肉/瘦猪颈肉 into 3cm cubes, place in 800ml cold water, boil for 3 mins and rinse.","step_tl":"Hiwain ang 300g na 高品质原切牛肉/瘦猪颈肉 sa 3cm, ilagay sa 800ml malamig na tubig, pakuluan ng 3 minuto."},{"zone":"B","step_zh":"将150g自然熟有机大番茄切成4cm的滚刀块备用。","step_en":"Cut 150g of 自然熟有机大番茄 into 4cm chunks.","step_tl":"Hiwain ang 150g na 自然熟有机大番茄 sa 4cm na tipak."},{"zone":"C","step_zh":"准备15g大料（八角2颗、香叶3片、桂皮1小块）及20g葱姜蒜。","step_en":"Prepare 15g spices (2 star anise, 3 bay leaves, 1 cinnamon) and 20g aromatics.","step_tl":"Ihanda ang 15g pampalasa at 20g sibuyas, luya, bawang."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 热锅下15ml食用油，烧热后放入焯水后的高品质原切牛肉/瘦猪颈肉，微煎2分钟至表面微焦黄","time_seconds":120},{"step_zh":"[大火转小火/High to Low] 加入800ml沸水及15g香辛料，大火烧开后转最小火加盖慢炖40分钟","time_seconds":2400},{"step_zh":"[小火/Low Heat] 加入切好的150g自然熟有机大番茄，继续加盖焖煮20分钟至软糯","time_seconds":1200},{"step_zh":"[大火/High Heat] 开大火收浓汤汁（约5分钟），加入3g盐调味后出锅","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('53a19a95-ffc0-48f2-b03e-b16d8017b8d7', '低脂低卡鲜烤鸡腿', 'western', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g的农家散养清远鸡肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 农家散养清远鸡肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 农家散养清远鸡肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的农家散养清远鸡肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将农家散养清远鸡肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的农家散养清远鸡肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c4272b5e-eef1-48ff-95d7-df3a47c03852', '脆皮纯肉烤肠卷', 'western', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g的有机精选瘦猪肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 有机精选瘦猪肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的有机精选瘦猪肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将有机精选瘦猪肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的有机精选瘦猪肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('69a5a70f-f7c1-4f82-996d-be1181d1075c', '高纤无糖巧克力麦芬', 'western', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g可生食无菌土鸡蛋表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 可生食无菌土鸡蛋, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 可生食无菌土鸡蛋, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g可生食无菌土鸡蛋，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在可生食无菌土鸡蛋表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与可生食无菌土鸡蛋装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('983891b6-a288-4262-ba85-4ad9e57c9c52', '低脂鲜蔬泰罗勒肉碎', 'southeast_asian', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('32885162-ed0c-4cee-a1aa-47fdf5662cd3', '鲜香干锅花菜', 'sichuan', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('cb86f65b-a789-4439-9cea-7e09abfda7a6', '少油干炒牛河', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 高品质原切牛肉/瘦猪颈肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 高品质原切牛肉/瘦猪颈肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的高品质原切牛肉/瘦猪颈肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回高品质原切牛肉/瘦猪颈肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a7406bde-2525-4266-8eeb-ebd92fa16a53', '高蛋白蒜蓉蒸虾', 'sichuan', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g深海白对虾/活虾，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 深海白对虾/活虾 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 深海白对虾/活虾 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g有机香辛料(提香解腻)切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 有机香辛料(提香解腻) into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 有机香辛料(提香解腻) sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有深海白对虾/活虾的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e7cdfcef-1ea1-4815-aa8e-37d928f01044', '脱脂奶炼乳冰咖啡', 'southeast_asian', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g低脂高钙纯牛奶/低脂干酪切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 低脂高钙纯牛奶/低脂干酪 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 低脂高钙纯牛奶/低脂干酪 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的低脂高钙纯牛奶/低脂干酪，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的低脂高钙纯牛奶/低脂干酪回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8e950016-df85-4224-bda6-88fd2911f3bd', '养胃皮蛋瘦肉粥', 'cantonese', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将有机精选瘦猪肉切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 有机精选瘦猪肉 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 有机精选瘦猪肉 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和有机精选瘦猪肉迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6f917c86-9a21-4561-a789-4e85618ede53', '空气炸锅全麦油条', 'jiangnan', '{default}', '{detox}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7f5d8b06-8b9a-4b17-99e8-27f01de5d2f4', '低卡鲜蔬凯撒沙拉', 'western', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将150g的有机生鲜绿叶蔬菜彻底清洗干净，特别是生蔬菜必须在净水中泡10分钟，最后用脱水机彻底甩干水分。","step_en":"Wash 150g 有机生鲜绿叶蔬菜 thoroughly, soak greens in cold water, spin dry completely.","step_tl":"Hugasan ang 有机生鲜绿叶蔬菜, ibabad sa malamig na tubig, patuyuin."},{"zone":"B","step_zh":"处理150g的天然粗粮黑小麦/综合高蛋白主料（若非即食肉类则应提前用水煮或低油煎熟），将其切成小块或手撕成小片。","step_en":"Prepare 150g 天然粗粮黑小麦/综合高蛋白 (boil or sear if meat), cut or shred.","step_tl":"Ihanda ang 天然粗粮黑小麦/综合高蛋白, hiwain o punitin."},{"zone":"C","step_zh":"调配低卡油醋汁：30ml橄榄油、10ml纯果醋、5g蜂蜜、2g现磨粗粒黑胡椒及3g海盐混合摇匀至乳化。","step_en":"Mix vinaigrette: 3tbsp olive oil, 1tbsp vinegar, honey, pepper and salt.","step_tl":"Gawin ang sauce: oil, vinegar, honey, asin, paminta."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 取一个有深度的干净大沙拉碗，将沥干水分的爽翠有机生鲜绿叶蔬菜作为最下层积底平铺","time_seconds":30},{"step_zh":"[常温/Room Temp] 在铺好的蔬菜层上整齐地放上准备好的天然粗粮黑小麦/综合高蛋白。此时可依据喜好点缀小番茄或10g坚果碎补充营养","time_seconds":30},{"step_zh":"[常温/Room Temp] 食用前一分钟才均匀地淋上充分乳化调好的油醋沙拉汁，可使用沙拉夹稍微低手翻拌入味","time_seconds":30},{"step_zh":"[常温/Room Temp] 摆盘装面，若准备有全麦低脂面包丁则应最后撒上以长久保持其酥脆口感","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('77325ec7-7d18-4c80-b22a-efcd8df0e19a', '高钙新鲜纯牛奶', 'jiangnan', '{sweet}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c5eae2bd-25b6-48f1-b23f-a1a6b1e1fd69', '少油版地三鲜', 'sichuan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0036e773-1870-481c-a0dd-b13340df5fee', '清蒸高蛋白海鱼', 'cantonese', '{light}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g深海高蛋白鲜鱼，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 深海高蛋白鲜鱼 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 深海高蛋白鲜鱼 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有深海高蛋白鲜鱼的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('349b4147-892e-4b53-91ec-6d94f902a944', '无糖新鲜水果酸奶杯', 'western', '{sour}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g低脂高钙纯牛奶/低脂干酪切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 低脂高钙纯牛奶/低脂干酪 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 低脂高钙纯牛奶/低脂干酪 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g时令新鲜无公害水果清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 时令新鲜无公害水果 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 时令新鲜无公害水果 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的低脂高钙纯牛奶/低脂干酪，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g时令新鲜无公害水果，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的低脂高钙纯牛奶/低脂干酪回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bb9011f4-6f7e-414a-a77a-4afe4814cabc', '无油香茅柠檬去骨鸡', 'southeast_asian', '{sour}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g时令新鲜无公害水果清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 时令新鲜无公害水果 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 时令新鲜无公害水果 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g时令新鲜无公害水果，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('4fd23f72-a114-4b75-b454-23f6b7e66c25', '粗粮粉蒸肉', 'sichuan', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将有机精选瘦猪肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 有机精选瘦猪肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的有机精选瘦猪肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回有机精选瘦猪肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('825f2b45-f39a-463b-b9a1-14b2b7ad6857', '干煸嫩四季豆', 'sichuan', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('23d13f81-0004-4123-a6bb-82cdd0dffd20', '无糖燕麦烤箱苹果派', 'western', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g的天然粗粮黑小麦/综合高蛋白表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的时令新鲜无公害水果切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 时令新鲜无公害水果 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 时令新鲜无公害水果, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的天然粗粮黑小麦/综合高蛋白放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将天然粗粮黑小麦/综合高蛋白彻底翻一个面，并在四周空隙处铺排上时令新鲜无公害水果","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的天然粗粮黑小麦/综合高蛋白表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2a8ad61e-1486-4e43-991f-2240f0661c42', '少油手抓饼加双蛋', 'jiangnan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将200g可生食无菌土鸡蛋切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 可生食无菌土鸡蛋 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 可生食无菌土鸡蛋 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入可生食无菌土鸡蛋，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('deb5485a-00c7-43a0-8b5b-17a4459ff009', '低糖红豆冰', 'cantonese', '{sweet}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('adbcd334-c82a-48e9-a211-50777e9cc096', '高蛋白黑椒嫩牛柳', 'cantonese', '{spicy}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('9bef7a46-1850-4a68-bd83-5b0afe443966', '水煮土鸡蛋火腿全麦包', 'jiangnan', '{light}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将200g农家散养清远鸡肉切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 农家散养清远鸡肉 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 农家散养清远鸡肉 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入农家散养清远鸡肉，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2b1254ae-3535-494f-a306-609f7aacd39e', '全麦火腿芝士三明治', 'western', '{default}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将2片全麦面包/汉堡胚从中间切开，放入吐司炉或平底锅微微烘烤至表面微焦酥脆。","step_en":"Toast bread or burger buns until slightly crispy on the surface.","step_tl":"I-toast ang tinapay hanggang maging crispy."},{"zone":"B","step_zh":"将有机精选瘦猪肉处理熟透（可香煎、微波加热或水煮断生），并单独煎制一个太阳蛋备用。","step_en":"Cook/sear the 有机精选瘦猪肉 slices, and fry a sunny-side-up egg.","step_tl":"Lutuin ang 有机精选瘦猪肉 at magprito ng itlog."},{"zone":"C","step_zh":"仔细洗净并用厨房纸擦干四季时鲜杂蔬拼盘，切几片新鲜熟番茄和爽脆洋葱圈用作解腻内馅。","step_en":"Wash and dry 四季时鲜杂蔬拼盘, slice tomatoes and onions for filling.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, hiwain ang kamatis at sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 铺平一片烘烤好的面包/汉堡底胚，在接触面均匀涂抹10g沙拉酱或5g低脂黄油保护面包","time_seconds":30},{"step_zh":"[常温/Room Temp] 依次叠加上一层平铺的四季时鲜杂蔬拼盘、煎熟且沥干油脂的有机精选瘦猪肉、清爽的番茄洋葱片及荷包蛋","time_seconds":45},{"step_zh":"[常温/Room Temp] 根据喜好面上加覆一片低脂芝士，最后盖上另一片面包顶胚","time_seconds":15},{"step_zh":"[中火/Medium Heat] （可选）用食品防油纸或保鲜膜紧紧包裹定型，然后从中间一刀对半切开方便大口食用","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('eaa0af7f-9f65-4a1c-a461-e3f6c9905993', '无油香烤鸭腿', 'sichuan', '{light}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g的新鲜散养瘦鸭肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 新鲜散养瘦鸭肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 新鲜散养瘦鸭肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的新鲜散养瘦鸭肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将新鲜散养瘦鸭肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的新鲜散养瘦鸭肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('1484e555-e8be-467f-9a70-2fc67c9f565d', '少油红烧茄子', 'sichuan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g新鲜紫皮鲜茄子清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 新鲜紫皮鲜茄子 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 新鲜紫皮鲜茄子 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g新鲜紫皮鲜茄子，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('489b3f9b-d5eb-490a-85ce-3b31e1c43e9d', '少油干炒牛河', 'jiangnan', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 高品质原切牛肉/瘦猪颈肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 高品质原切牛肉/瘦猪颈肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的高品质原切牛肉/瘦猪颈肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回高品质原切牛肉/瘦猪颈肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5c956990-a5fc-4eb2-947d-c0eee227a4f0', '高锌杂粮黄咖喱海鲜', 'southeast_asian', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g优质海鲜干贝类切成3cm大块，加入10ml青柠汁抓匀去除腥味。","step_en":"Cut 300g of 优质海鲜干贝类 into 3cm chunks, mix with 10ml lime juice.","step_tl":"Hiwain ang 300g ng 优质海鲜干贝类 sa 3cm, haluan ng 10ml lime juice."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切块洗净备用。","step_en":"Cut and wash 150g of 四季时鲜杂蔬拼盘.","step_tl":"Hiwain at hugasan ang 150g ng 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备50g冬阴功酱/绿咖喱酱，200ml椰浆，1根香茅(拍碎)，2片柠檬叶。","step_en":"Prepare 50g curry paste, 200ml coconut milk, 1 bruised lemongrass, 2 kaffir lime leaves.","step_tl":"Ihanda ang 50g curry paste, 200ml coconut milk, 1 tanglad, 2 dahon ng dayap."}]}'::jsonb, '{"steps":[{"step_zh":"[中小火/Med-Low Heat] 锅中加10ml油，放入50g咖喱酱和香茅，小火慢炒60秒炒出红油香味。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 倒入200ml椰浆和100ml清水，大火煮沸。","time_seconds":120},{"step_zh":"[中火/Medium Heat] 放入300g优质海鲜干贝类和柠檬叶，加盖中小火炖煮10分钟。","time_seconds":600},{"step_zh":"[中大火/Med-High Heat] 加入150g四季时鲜杂蔬拼盘继续炖煮3分钟，临出锅加5ml鱼露提鲜。","time_seconds":180}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('14d7fcca-6636-467b-b485-1348d5e106f1', '减糖版糖醋里脊', 'sichuan', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f83fbf0d-5c75-4300-8213-612a11d1805d', '低脂健康香锅', 'sichuan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5df696b3-b688-487b-8a82-560153c87ca2', '低脂原味香煎豆腐', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c7f3c0cf-627b-41d6-a3da-f30dc74cbae7', '少油单面煎荷包蛋', 'jiangnan', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将可生食无菌土鸡蛋切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 可生食无菌土鸡蛋, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 可生食无菌土鸡蛋, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的可生食无菌土鸡蛋滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回可生食无菌土鸡蛋煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('529fd24a-8b54-4380-85bc-5925352745f4', '清蒸鲜活鲈鱼', 'sichuan', '{light}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g深海高蛋白鲜鱼，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 深海高蛋白鲜鱼 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 深海高蛋白鲜鱼 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有深海高蛋白鲜鱼的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('94020e2d-173b-4070-b84c-e261d80a63f0', '高蛋白电饭煲沙姜鸡', 'cantonese', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成3cm见方的块，放入800ml冷水锅中，大火烧开焯水3分钟，捞出洗净血沫。","step_en":"Cut 300g of 农家散养清远鸡肉 into 3cm cubes, place in 800ml cold water, boil for 3 mins and rinse.","step_tl":"Hiwain ang 300g na 农家散养清远鸡肉 sa 3cm, ilagay sa 800ml malamig na tubig, pakuluan ng 3 minuto."},{"zone":"B","step_zh":"将150g有机香辛料(提香解腻)切成4cm的滚刀块备用。","step_en":"Cut 150g of 有机香辛料(提香解腻) into 4cm chunks.","step_tl":"Hiwain ang 150g na 有机香辛料(提香解腻) sa 4cm na tipak."},{"zone":"C","step_zh":"准备15g大料（八角2颗、香叶3片、桂皮1小块）及20g葱姜蒜。","step_en":"Prepare 15g spices (2 star anise, 3 bay leaves, 1 cinnamon) and 20g aromatics.","step_tl":"Ihanda ang 15g pampalasa at 20g sibuyas, luya, bawang."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 热锅下15ml食用油，烧热后放入焯水后的农家散养清远鸡肉，微煎2分钟至表面微焦黄","time_seconds":120},{"step_zh":"[大火转小火/High to Low] 加入800ml沸水及15g香辛料，大火烧开后转最小火加盖慢炖40分钟","time_seconds":2400},{"step_zh":"[小火/Low Heat] 加入切好的150g有机香辛料(提香解腻)，继续加盖焖煮20分钟至软糯","time_seconds":1200},{"step_zh":"[大火/High Heat] 开大火收浓汤汁（约5分钟），加入3g盐调味后出锅","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('18420873-b4da-445c-9ccc-268832670592', '杂蔬广式炒饭', 'cantonese', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备300g隔夜冷藏米饭，用3ml食用油或清水在碗中提前抓散成颗粒状防粘。","step_en":"Prepare 300g leftover rice, break into grains with a little oil or water.","step_tl":"Ihanda ang 300g na kanin, paghiwalayin ang butil."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成约1cm见方的小丁；同时将四季时鲜杂蔬拼盘洗净也切成同等大小的碎丁保持口感统一。","step_en":"Dice 天然粗粮黑小麦/综合高蛋白 into 1cm cubes; wash and completely dice 四季时鲜杂蔬拼盘.","step_tl":"Tadtarin ang 天然粗粮黑小麦/综合高蛋白 at 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"碗中打散2个鸡蛋搅匀成蛋液，并备好提香的葱花。","step_en":"Beat 2 eggs evenly, prepare chopped scallions.","step_tl":"Batihin ang 2 itlog, ihanda ang sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧热炒锅倒入15ml食用油，倒入打散的鸡蛋液，快速炒熟盛出并略微切碎后备用","time_seconds":60},{"step_zh":"[中火/Medium Heat] 锅底补5ml底油，下入天然粗粮黑小麦/综合高蛋白丁煸炒至断生表面微缩，接着下入四季时鲜杂蔬拼盘丁炒出明香","time_seconds":120},{"step_zh":"[大火/High Heat] 倒入提前抓散的米饭，转大火快速持续翻炒按压，让每一粒米均匀受热","time_seconds":180},{"step_zh":"[大火/High Heat] 将炒好的鸡蛋倒回锅中，加入10ml生抽、2g盐和10g葱花，大火颠锅翻炒30秒产生锅气出炉","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('477f5e76-2508-4d64-bd67-5201dad736a7', '减油红油螺蛳粉', 'jiangnan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c36f0dc9-82d7-449e-94fc-05e6f8c408a9', '无糖破壁机纯豆浆', 'jiangnan', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成3cm见方的块，放入800ml冷水锅中，大火烧开焯水3分钟，捞出洗净血沫。","step_en":"Cut 300g of 非转基因大豆/老豆腐 into 3cm cubes, place in 800ml cold water, boil for 3 mins and rinse.","step_tl":"Hiwain ang 300g na 非转基因大豆/老豆腐 sa 3cm, ilagay sa 800ml malamig na tubig, pakuluan ng 3 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成4cm的滚刀块备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 4cm chunks.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa 4cm na tipak."},{"zone":"C","step_zh":"准备15g大料（八角2颗、香叶3片、桂皮1小块）及20g葱姜蒜。","step_en":"Prepare 15g spices (2 star anise, 3 bay leaves, 1 cinnamon) and 20g aromatics.","step_tl":"Ihanda ang 15g pampalasa at 20g sibuyas, luya, bawang."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 热锅下15ml食用油，烧热后放入焯水后的非转基因大豆/老豆腐，微煎2分钟至表面微焦黄","time_seconds":120},{"step_zh":"[大火转小火/High to Low] 加入800ml沸水及15g香辛料，大火烧开后转最小火加盖慢炖40分钟","time_seconds":2400},{"step_zh":"[小火/Low Heat] 加入切好的150g四季时鲜杂蔬拼盘，继续加盖焖煮20分钟至软糯","time_seconds":1200},{"step_zh":"[大火/High Heat] 开大火收浓汤汁（约5分钟），加入3g盐调味后出锅","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('1067453f-d9d5-4c34-9e19-0442c05d2be4', '少油全麦南洋炒通心粉', 'southeast_asian', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f7605c48-c27c-4e1f-92db-441c23805407', '无添加鲜果粒酸奶', 'jiangnan', '{sour}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g低脂高钙纯牛奶/低脂干酪切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 低脂高钙纯牛奶/低脂干酪 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 低脂高钙纯牛奶/低脂干酪 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g时令新鲜无公害水果清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 时令新鲜无公害水果 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 时令新鲜无公害水果 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的低脂高钙纯牛奶/低脂干酪，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g时令新鲜无公害水果，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的低脂高钙纯牛奶/低脂干酪回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bfce8f82-fdc7-4da2-b98c-098944d55e9e', '温润有机白米粥', 'jiangnan', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和天然粗粮黑小麦/综合高蛋白迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0eea1b4f-5f34-4bba-934c-814211664087', '高蛋白越南鲜牛肉河粉', 'southeast_asian', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 高品质原切牛肉/瘦猪颈肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 高品质原切牛肉/瘦猪颈肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的高品质原切牛肉/瘦猪颈肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回高品质原切牛肉/瘦猪颈肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e66dc5da-b52c-4f87-ae7f-785cb794588c', '无油空气炸锅薯角', 'western', '{light}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g天然粗粮黑小麦/综合高蛋白表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 天然粗粮黑小麦/综合高蛋白, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 天然粗粮黑小麦/综合高蛋白, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g生态黄心小土豆/紫薯切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 生态黄心小土豆/紫薯 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 生态黄心小土豆/紫薯 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g天然粗粮黑小麦/综合高蛋白，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在天然粗粮黑小麦/综合高蛋白表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g生态黄心小土豆/紫薯约90秒，与天然粗粮黑小麦/综合高蛋白装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('4910dad0-66f8-4059-bfd1-6aab4c26be75', '鲜香泰式无骨凤爪', 'southeast_asian', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b6fa03d0-4e1f-45a4-b98c-87fd952fb5ea', '开胃低卡酸辣清汤', 'southeast_asian', '{sour}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 天然粗粮黑小麦/综合高蛋白, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 天然粗粮黑小麦/综合高蛋白, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的天然粗粮黑小麦/综合高蛋白和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('060e87dd-3c85-46a9-aba7-84978c45ec2e', '原汁清汤瘦牛腩', 'cantonese', '{light}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 高品质原切牛肉/瘦猪颈肉, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 高品质原切牛肉/瘦猪颈肉, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的高品质原切牛肉/瘦猪颈肉和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0e115f9b-7e61-4b6b-9f55-e1ca338ebe0e', '维C新鲜菠萝炒饭', 'southeast_asian', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"准备300g隔夜冷藏米饭，用3ml食用油或清水在碗中提前抓散成颗粒状防粘。","step_en":"Prepare 300g leftover rice, break into grains with a little oil or water.","step_tl":"Ihanda ang 300g na kanin, paghiwalayin ang butil."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成约1cm见方的小丁；同时将时令新鲜无公害水果洗净也切成同等大小的碎丁保持口感统一。","step_en":"Dice 天然粗粮黑小麦/综合高蛋白 into 1cm cubes; wash and completely dice 时令新鲜无公害水果.","step_tl":"Tadtarin ang 天然粗粮黑小麦/综合高蛋白 at 时令新鲜无公害水果."},{"zone":"C","step_zh":"碗中打散2个鸡蛋搅匀成蛋液，并备好提香的葱花。","step_en":"Beat 2 eggs evenly, prepare chopped scallions.","step_tl":"Batihin ang 2 itlog, ihanda ang sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧热炒锅倒入15ml食用油，倒入打散的鸡蛋液，快速炒熟盛出并略微切碎后备用","time_seconds":60},{"step_zh":"[中火/Medium Heat] 锅底补5ml底油，下入天然粗粮黑小麦/综合高蛋白丁煸炒至断生表面微缩，接着下入时令新鲜无公害水果丁炒出明香","time_seconds":120},{"step_zh":"[大火/High Heat] 倒入提前抓散的米饭，转大火快速持续翻炒按压，让每一粒米均匀受热","time_seconds":180},{"step_zh":"[大火/High Heat] 将炒好的鸡蛋倒回锅中，加入10ml生抽、2g盐和10g葱花，大火颠锅翻炒30秒产生锅气出炉","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e9215df2-a009-46a2-b859-63b145895630', '低脂芝士烤热狗', 'western', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将2片全麦面包/汉堡胚从中间切开，放入吐司炉或平底锅微微烘烤至表面微焦酥脆。","step_en":"Toast bread or burger buns until slightly crispy on the surface.","step_tl":"I-toast ang tinapay hanggang maging crispy."},{"zone":"B","step_zh":"将低脂高钙纯牛奶/低脂干酪处理熟透（可香煎、微波加热或水煮断生），并单独煎制一个太阳蛋备用。","step_en":"Cook/sear the 低脂高钙纯牛奶/低脂干酪 slices, and fry a sunny-side-up egg.","step_tl":"Lutuin ang 低脂高钙纯牛奶/低脂干酪 at magprito ng itlog."},{"zone":"C","step_zh":"仔细洗净并用厨房纸擦干四季时鲜杂蔬拼盘，切几片新鲜熟番茄和爽脆洋葱圈用作解腻内馅。","step_en":"Wash and dry 四季时鲜杂蔬拼盘, slice tomatoes and onions for filling.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, hiwain ang kamatis at sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 铺平一片烘烤好的面包/汉堡底胚，在接触面均匀涂抹10g沙拉酱或5g低脂黄油保护面包","time_seconds":30},{"step_zh":"[常温/Room Temp] 依次叠加上一层平铺的四季时鲜杂蔬拼盘、煎熟且沥干油脂的低脂高钙纯牛奶/低脂干酪、清爽的番茄洋葱片及荷包蛋","time_seconds":45},{"step_zh":"[常温/Room Temp] 根据喜好面上加覆一片低脂芝士，最后盖上另一片面包顶胚","time_seconds":15},{"step_zh":"[中火/Medium Heat] （可选）用食品防油纸或保鲜膜紧紧包裹定型，然后从中间一刀对半切开方便大口食用","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0b41ee66-36a9-40ec-b5aa-70464f4959ce', '低卡瘦火腿生菜薄饼', 'jiangnan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将200g有机精选瘦猪肉切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 有机精选瘦猪肉 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 有机精选瘦猪肉 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g有机生鲜绿叶蔬菜洗净切碎备用。","step_en":"Wash and chop 100g of 有机生鲜绿叶蔬菜.","step_tl":"Hugasan at tadtarin ang 100g na 有机生鲜绿叶蔬菜."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入有机精选瘦猪肉，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入有机生鲜绿叶蔬菜，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5e292124-3089-471b-9e21-a174712c5763', '酸汤开胃肥牛', 'sichuan', '{sour}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 高品质原切牛肉/瘦猪颈肉, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 高品质原切牛肉/瘦猪颈肉, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的高品质原切牛肉/瘦猪颈肉和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7c65ff94-a125-4a4e-9fdb-d02cb458a516', '高纤糙米生南瓜粥', 'jiangnan', '{default}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和天然粗粮黑小麦/综合高蛋白迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c22050e8-ed17-4f1c-ae55-4cfd97fbe00b', '高蛋白鸡蛋煎饼', 'cantonese', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0f882798-1e92-4419-8aba-3921e1418d98', '花生酱拌有机生菜', 'southeast_asian', '{salty}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5ce95ddf-36af-49e2-98e5-317ce8ba4e9e', '少油电饭煲海南鸡饭', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成3cm见方的块，放入800ml冷水锅中，大火烧开焯水3分钟，捞出洗净血沫。","step_en":"Cut 300g of 农家散养清远鸡肉 into 3cm cubes, place in 800ml cold water, boil for 3 mins and rinse.","step_tl":"Hiwain ang 300g na 农家散养清远鸡肉 sa 3cm, ilagay sa 800ml malamig na tubig, pakuluan ng 3 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成4cm的滚刀块备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 4cm chunks.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa 4cm na tipak."},{"zone":"C","step_zh":"准备15g大料（八角2颗、香叶3片、桂皮1小块）及20g葱姜蒜。","step_en":"Prepare 15g spices (2 star anise, 3 bay leaves, 1 cinnamon) and 20g aromatics.","step_tl":"Ihanda ang 15g pampalasa at 20g sibuyas, luya, bawang."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 热锅下15ml食用油，烧热后放入焯水后的农家散养清远鸡肉，微煎2分钟至表面微焦黄","time_seconds":120},{"step_zh":"[大火转小火/High to Low] 加入800ml沸水及15g香辛料，大火烧开后转最小火加盖慢炖40分钟","time_seconds":2400},{"step_zh":"[小火/Low Heat] 加入切好的150g四季时鲜杂蔬拼盘，继续加盖焖煮20分钟至软糯","time_seconds":1200},{"step_zh":"[大火/High Heat] 开大火收浓汤汁（约5分钟），加入3g盐调味后出锅","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('665652a9-b1d2-4f0a-b3ad-f6103a0c9f0a', '低脂空气炸泰烤肉', 'southeast_asian', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g的有机精选瘦猪肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 有机精选瘦猪肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的有机精选瘦猪肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将有机精选瘦猪肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的有机精选瘦猪肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('88ecf9d0-9b91-4d16-98d1-64b51cc504c5', '低脂鲜奶蘑菇汤', 'western', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将低脂高钙纯牛奶/低脂干酪洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 低脂高钙纯牛奶/低脂干酪, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 低脂高钙纯牛奶/低脂干酪, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将高山天然鲜菌菇切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 高山天然鲜菌菇 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 高山天然鲜菌菇, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的低脂高钙纯牛奶/低脂干酪和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的高山天然鲜菌菇块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d51247d2-befb-4618-afd9-9a663ad6a0d7', '夏威夷全麦小披萨', 'western', '{default}', '{detox}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"准备一张发好的披萨饼底（也可用低脂墨西哥卷饼代替），在其表面均匀平涂一层番茄披萨底酱。","step_en":"Prepare a pizza crust (or tortilla), spread tomato pizza sauce evenly.","step_tl":"Ihanda ang pizza crust, lagyan ng tomato sauce."},{"zone":"B","step_zh":"将主食材天然粗粮黑小麦/综合高蛋白切成均匀薄片或小块，在底盘薄薄先撒上一层马苏里拉拉丝芝士。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 thinly, sprinkle a light layer of mozzarella cheese on the base.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, lagyan ng cheese sa ibabaw."},{"zone":"C","step_zh":"洗净四季时鲜杂蔬拼盘切小块，用厨房纸充分吸干多余水分防止塌陷；烤箱提前预热至200°C。","step_en":"Wash and dice 四季时鲜杂蔬拼盘, preheat oven to 200°C.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, i-preheat ang oven sa 200°C."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将天然粗粮黑小麦/综合高蛋白片和脱去水分的四季时鲜杂蔬拼盘块美观、均匀地铺满在披萨饼面上","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 在最上面再厚厚地撒上一层诱人的马苏里拉拉丝芝士封层","time_seconds":30},{"step_zh":"[烤箱200°C/Oven] 迅速送入预热好的烤箱中层，设置上下火200°C安全烘烤约15分钟","time_seconds":900},{"step_zh":"[常温/Room Temp] 密切观察表面芝士完全融化并呈现金黄微焦状后取出，滚刀切成扇形拉丝食用","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('954ecc2b-2b76-4400-bf05-b10cc17f2494', '少油虾酱炒通菜', 'cantonese', '{salty}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('12d76ee6-8653-4c5b-9945-c00d2c4ddfd3', '低卡魔芋代餐酸辣粉', 'jiangnan', '{sour}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d4d49c49-6f79-4399-9cbe-d9c3d82f1daa', '补血生滚猪肝粥', 'cantonese', '{default}', '{pregnancy}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将有机精选瘦猪肉切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 有机精选瘦猪肉 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 有机精选瘦猪肉 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和有机精选瘦猪肉迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('957e7e9d-b194-4881-9135-f0345da64383', '优质蛋白水煮土鸡蛋', 'jiangnan', '{light}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('9994910f-122e-4a27-9a2c-2d4803fad285', '高蛋白生炒牛肉饭', 'cantonese', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bff6adba-cea2-4692-8867-74d758f8031b', '手打咸鱼瘦肉饼', 'cantonese', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f2fef3e0-39b2-433a-b28c-846e6d9f7905', '高纤抗氧化蔬菜沙拉', 'western', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将150g的有机生鲜绿叶蔬菜彻底清洗干净，特别是生蔬菜必须在净水中泡10分钟，最后用脱水机彻底甩干水分。","step_en":"Wash 150g 有机生鲜绿叶蔬菜 thoroughly, soak greens in cold water, spin dry completely.","step_tl":"Hugasan ang 有机生鲜绿叶蔬菜, ibabad sa malamig na tubig, patuyuin."},{"zone":"B","step_zh":"处理150g的天然粗粮黑小麦/综合高蛋白主料（若非即食肉类则应提前用水煮或低油煎熟），将其切成小块或手撕成小片。","step_en":"Prepare 150g 天然粗粮黑小麦/综合高蛋白 (boil or sear if meat), cut or shred.","step_tl":"Ihanda ang 天然粗粮黑小麦/综合高蛋白, hiwain o punitin."},{"zone":"C","step_zh":"调配低卡油醋汁：30ml橄榄油、10ml纯果醋、5g蜂蜜、2g现磨粗粒黑胡椒及3g海盐混合摇匀至乳化。","step_en":"Mix vinaigrette: 3tbsp olive oil, 1tbsp vinegar, honey, pepper and salt.","step_tl":"Gawin ang sauce: oil, vinegar, honey, asin, paminta."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 取一个有深度的干净大沙拉碗，将沥干水分的爽翠有机生鲜绿叶蔬菜作为最下层积底平铺","time_seconds":30},{"step_zh":"[常温/Room Temp] 在铺好的蔬菜层上整齐地放上准备好的天然粗粮黑小麦/综合高蛋白。此时可依据喜好点缀小番茄或10g坚果碎补充营养","time_seconds":30},{"step_zh":"[常温/Room Temp] 食用前一分钟才均匀地淋上充分乳化调好的油醋沙拉汁，可使用沙拉夹稍微低手翻拌入味","time_seconds":30},{"step_zh":"[常温/Room Temp] 摆盘装面，若准备有全麦低脂面包丁则应最后撒上以长久保持其酥脆口感","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('4920ebdd-74e2-4ebf-bff0-614d84e32c3f', '高钙紫菜虾皮胡辣汤', 'jiangnan', '{spicy}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将深海白对虾/活虾洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 深海白对虾/活虾, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 深海白对虾/活虾, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将有机生鲜绿叶蔬菜切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 有机生鲜绿叶蔬菜 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 有机生鲜绿叶蔬菜, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的深海白对虾/活虾和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的有机生鲜绿叶蔬菜块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('24cfcdd7-be76-4caa-a9b0-5af03ed104dd', '高蛋白鲜虾荞麦面', 'southeast_asian', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将深海白对虾/活虾切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 深海白对虾/活虾, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 深海白对虾/活虾, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的深海白对虾/活虾滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回深海白对虾/活虾煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('53bd3099-1e98-496d-b828-666a3cdaddb1', '低卡鲜鱼蛋', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g深海高蛋白鲜鱼切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海高蛋白鲜鱼 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海高蛋白鲜鱼 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海高蛋白鲜鱼，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海高蛋白鲜鱼回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d1d53212-7ea7-4255-aedf-4043af15cfa9', '高钙低脂芝士焗蛋', 'western', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('95ae30d1-02f3-4d6d-85e5-ee1c9095ad92', '原汁清蒸鱼块', 'sichuan', '{light}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g深海高蛋白鲜鱼，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 深海高蛋白鲜鱼 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 深海高蛋白鲜鱼 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有深海高蛋白鲜鱼的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('df2503d9-080b-4d3c-a2bf-80da3fef1b58', '新鲜白菜薄皮锅贴', 'jiangnan', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"准备发面或饺子皮，将天然粗粮黑小麦/综合高蛋白剁成细碎肉馅，加入10ml葱姜水顺时针搅拌上劲。","step_en":"Prepare dough, mince 天然粗粮黑小麦/综合高蛋白 and stir in ginger water to make filling.","step_tl":"Ihanda ang masa, tadtarin ang 天然粗粮黑小麦/综合高蛋白 at haluin ng tubig luya."},{"zone":"B","step_zh":"将有机生鲜绿叶蔬菜切碎，稍加盐腌制后挤干水分，与肉馅混合调味，包成包子或饺子。","step_en":"Chop 有机生鲜绿叶蔬菜, squeeze out water, mix with meat filling and wrap.","step_tl":"Tadtarin ang 有机生鲜绿叶蔬菜, pigain, haluin sa karne at balutin."},{"zone":"C","step_zh":"准备一小碗冷水和一撮黑芝麻、香葱末备用。","step_en":"Prepare a small bowl of cold water, some black sesame and chopped scallions.","step_tl":"Ihanda ang tubig at sesame."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 平底锅加5ml食用油烧热，将包好的面点底部朝下放入，煎约2分钟至底部微黄","time_seconds":120},{"step_zh":"[大火/High Heat] 顺锅边倒入清水，水量没过底部约三分之一，立即盖紧锅盖","time_seconds":10},{"step_zh":"[中火/Medium Heat] 保持中火水煎约8-10分钟，听到锅内水分烧干，发出“滋啦”声响即可","time_seconds":540},{"step_zh":"[小火/Low Heat] 开盖，撒上提前准备的黑芝麻和葱花，小火再煎1分钟将底部煎脆出锅","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c63dfc6d-3628-4f9c-b5f8-c83de8cca155', '鲜蔬沙茶牛肉', 'cantonese', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('00e2c6c1-7ed7-4af8-bf8b-ee08bcd1dffc', '减盐麻婆豆腐', 'sichuan', '{spicy}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d56da612-2e8f-4a5f-a804-caa621165e7a', '低脂纯奶香烤小土豆', 'western', '{sweet}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g的非转基因大豆/老豆腐表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 非转基因大豆/老豆腐, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 非转基因大豆/老豆腐, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的生态黄心小土豆/紫薯切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 生态黄心小土豆/紫薯 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 生态黄心小土豆/紫薯, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的非转基因大豆/老豆腐放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将非转基因大豆/老豆腐彻底翻一个面，并在四周空隙处铺排上生态黄心小土豆/紫薯","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的非转基因大豆/老豆腐表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b86ad5f1-b343-4aee-86d4-04742fa04ad9', '减油减盐风味小面', 'jiangnan', '{salty}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5808655f-0258-4e8e-b117-1815c5f41682', '少油鱼香茄子', 'sichuan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g深海高蛋白鲜鱼切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海高蛋白鲜鱼 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海高蛋白鲜鱼 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g新鲜紫皮鲜茄子清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 新鲜紫皮鲜茄子 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 新鲜紫皮鲜茄子 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海高蛋白鲜鱼，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g新鲜紫皮鲜茄子，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海高蛋白鲜鱼回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('caa1b8ab-bc81-4dfa-b481-d7a6315b4b98', '减盐豉汁蒸排骨', 'cantonese', '{salty}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g高品质原切牛肉/瘦猪颈肉，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 高品质原切牛肉/瘦猪颈肉 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 高品质原切牛肉/瘦猪颈肉 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有高品质原切牛肉/瘦猪颈肉的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a1834da2-383d-4fb0-aa2a-39b46fa1fd61', '植物黄油土豆泥', 'western', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g生态黄心小土豆/紫薯清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 生态黄心小土豆/紫薯 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 生态黄心小土豆/紫薯 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g生态黄心小土豆/紫薯，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d8df674a-a935-4fff-b467-50b71dcd8653', '农家少油回锅肉', 'sichuan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('fb4d5e3d-01e3-4c63-ae27-201c9829498b', '红烧瘦肉', 'sichuan', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('595d0092-bba1-4d6e-903c-fc181ba075fd', '低脂培根煎太阳蛋', 'western', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g有机精选瘦猪肉表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 有机精选瘦猪肉, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 有机精选瘦猪肉, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g有机精选瘦猪肉，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在有机精选瘦猪肉表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与有机精选瘦猪肉装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bbff0251-b63e-4351-9020-e313deb68074', '少油煎酿鲜茄子', 'cantonese', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g新鲜紫皮鲜茄子清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 新鲜紫皮鲜茄子 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 新鲜紫皮鲜茄子 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g新鲜紫皮鲜茄子，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('97407c7f-5f92-4211-b308-1bde1e76e963', '营养木须肉', 'sichuan', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f7a27bd2-d81f-4e14-84b4-e8bb99275aa8', '低脂嫩滑口水鸡', 'sichuan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('61f25d0e-d4fd-47ef-8992-73b8853ef54f', '高纤燃脂黑椒烤芦笋', 'western', '{spicy}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g的天然粗粮黑小麦/综合高蛋白表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的天然粗粮黑小麦/综合高蛋白放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将天然粗粮黑小麦/综合高蛋白彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的天然粗粮黑小麦/综合高蛋白表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5ae49a6c-7612-4b1b-a194-e485f306a568', '高蛋白水波蛋配吐司', 'western', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2dcbf6c6-5a64-44a0-b897-1f433ca2c874', '低脂烤包肉', 'sichuan', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g的有机精选瘦猪肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 有机精选瘦猪肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的有机精选瘦猪肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将有机精选瘦猪肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的有机精选瘦猪肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('40f4304d-15bf-4b63-b4a9-ef185aa803d3', '低脂鱼香肉丝', 'sichuan', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f4c396c4-cc5b-4dd1-9b19-46083b050285', '原汁黄焖鸡', 'sichuan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('97a61884-3e6e-43a2-b9a7-206b59ea2fa4', '低脂越香煎瘦肉饼', 'southeast_asian', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b231ddd3-3419-4f27-be57-22a05543c890', '手工大虾云吞面', 'cantonese', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将深海白对虾/活虾切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 深海白对虾/活虾, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 深海白对虾/活虾, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的深海白对虾/活虾滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回深海白对虾/活虾煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('53e2a975-a11d-42f8-87cd-24977c8afb67', '低脂卤水鸡翅', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('eed48baa-cafd-40b5-bfdd-26b0f352258e', '无糖黑巧克力布朗尼', 'western', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('ed2667d3-bb26-4997-b846-938029f6a6bb', '营养满分瘦肉酿豆腐', 'southeast_asian', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('214183cc-f65c-4a26-a82c-911742e71305', '高脂低卡自制牛肉汉堡', 'western', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将2片全麦面包/汉堡胚从中间切开，放入吐司炉或平底锅微微烘烤至表面微焦酥脆。","step_en":"Toast bread or burger buns until slightly crispy on the surface.","step_tl":"I-toast ang tinapay hanggang maging crispy."},{"zone":"B","step_zh":"将高品质原切牛肉/瘦猪颈肉处理熟透（可香煎、微波加热或水煮断生），并单独煎制一个太阳蛋备用。","step_en":"Cook/sear the 高品质原切牛肉/瘦猪颈肉 slices, and fry a sunny-side-up egg.","step_tl":"Lutuin ang 高品质原切牛肉/瘦猪颈肉 at magprito ng itlog."},{"zone":"C","step_zh":"仔细洗净并用厨房纸擦干四季时鲜杂蔬拼盘，切几片新鲜熟番茄和爽脆洋葱圈用作解腻内馅。","step_en":"Wash and dry 四季时鲜杂蔬拼盘, slice tomatoes and onions for filling.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, hiwain ang kamatis at sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 铺平一片烘烤好的面包/汉堡底胚，在接触面均匀涂抹10g沙拉酱或5g低脂黄油保护面包","time_seconds":30},{"step_zh":"[常温/Room Temp] 依次叠加上一层平铺的四季时鲜杂蔬拼盘、煎熟且沥干油脂的高品质原切牛肉/瘦猪颈肉、清爽的番茄洋葱片及荷包蛋","time_seconds":45},{"step_zh":"[常温/Room Temp] 根据喜好面上加覆一片低脂芝士，最后盖上另一片面包顶胚","time_seconds":15},{"step_zh":"[中火/Medium Heat] （可选）用食品防油纸或保鲜膜紧紧包裹定型，然后从中间一刀对半切开方便大口食用","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('94abefd0-4747-47ea-8ed2-a0e041fe5640', '椰汁芒果糙米饭', 'southeast_asian', '{default}', '{detox}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g时令新鲜无公害水果清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 时令新鲜无公害水果 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 时令新鲜无公害水果 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g时令新鲜无公害水果，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a5c897a1-b231-4a82-89b0-64c7ddbe7545', '鲜蔬沙茶鱿鱼面', 'southeast_asian', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将深海高蛋白鲜鱼切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 深海高蛋白鲜鱼, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 深海高蛋白鲜鱼, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的深海高蛋白鲜鱼滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回深海高蛋白鲜鱼煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a92607ac-91d7-4658-a02a-b6a7443e5304', '五香卤牛腱肉', 'sichuan', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6a3913c9-4d9c-4785-a9d8-eaf7f6957ac3', '高钙低脂芝士焗通心粉', 'western', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将低脂高钙纯牛奶/低脂干酪切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 低脂高钙纯牛奶/低脂干酪, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 低脂高钙纯牛奶/低脂干酪, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的低脂高钙纯牛奶/低脂干酪滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回低脂高钙纯牛奶/低脂干酪煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('34175695-1098-42b9-aee9-6919f76874fc', '减盐咸蛋黄炒大虾仁', 'southeast_asian', '{salty}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bd97f2ee-9ebc-458c-9479-d86dbcf3b317', '鲜蔬星洲炒米粉', 'cantonese', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('90761577-65c1-456c-8043-3b3f0197a616', '低糖奶油猪', 'cantonese', '{sweet}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('cbedecf9-8319-4230-8728-818fac3780ed', '减糖菠萝包', 'cantonese', '{sweet}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g时令新鲜无公害水果清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 时令新鲜无公害水果 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 时令新鲜无公害水果 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g时令新鲜无公害水果，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('aa1d912e-ecd8-4205-80b5-28fbcacc5f30', '高纤燕麦核桃饼干', 'western', '{default}', '{detox}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('40179ae8-d4b8-4ec4-af99-831f553b2c76', '手工鲜肉小笼包', 'jiangnan', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将200g有机精选瘦猪肉切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 有机精选瘦猪肉 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 有机精选瘦猪肉 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入有机精选瘦猪肉，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e5db3d26-a613-44c5-b253-fd0890d5ff40', '少油姜葱爆大虾', 'cantonese', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g紫皮鲜洋葱/大葱清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 紫皮鲜洋葱/大葱 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 紫皮鲜洋葱/大葱 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g紫皮鲜洋葱/大葱，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('682bee88-bbea-4da0-ad8b-55e4d41bd1d9', '抗氧化洋葱炒蛋', 'cantonese', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g紫皮鲜洋葱/大葱清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 紫皮鲜洋葱/大葱 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 紫皮鲜洋葱/大葱 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g紫皮鲜洋葱/大葱，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('4676bba7-4a79-4f3b-9169-7b89cb2234bb', '低脂鲜咖喱牛腩', 'cantonese', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('ca46c426-c86b-4b66-a30c-e28b82cdc5d3', '农家杂蔬小炒肉', 'sichuan', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('08434b19-a4bf-4e48-85aa-ac4e957098c8', '非油炸烤鲜洋葱圈', 'western', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g的天然粗粮黑小麦/综合高蛋白表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的紫皮鲜洋葱/大葱切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 紫皮鲜洋葱/大葱 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 紫皮鲜洋葱/大葱, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的天然粗粮黑小麦/综合高蛋白放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将天然粗粮黑小麦/综合高蛋白彻底翻一个面，并在四周空隙处铺排上紫皮鲜洋葱/大葱","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的天然粗粮黑小麦/综合高蛋白表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('54cba9ec-2d6e-4e86-a4b3-a2e17496b761', '少油新鲜韭菜土鸡蛋盒', 'jiangnan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('bf20b538-41ad-45f2-9208-002e84e0dcf1', '鲜嫩油焖大虾', 'sichuan', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('27b77fdd-ae32-4e2f-853f-f0413daf9d39', '减盐豉汁蒸肉排', 'cantonese', '{salty}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g有机精选瘦猪肉，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 有机精选瘦猪肉 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 有机精选瘦猪肉 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有有机精选瘦猪肉的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('fb22b6b8-967a-4091-92c6-b7fe5086ca5a', '高钙蘑菇芝士全麦披萨', 'western', '{default}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备一张发好的披萨饼底（也可用低脂墨西哥卷饼代替），在其表面均匀平涂一层番茄披萨底酱。","step_en":"Prepare a pizza crust (or tortilla), spread tomato pizza sauce evenly.","step_tl":"Ihanda ang pizza crust, lagyan ng tomato sauce."},{"zone":"B","step_zh":"将主食材低脂高钙纯牛奶/低脂干酪切成均匀薄片或小块，在底盘薄薄先撒上一层马苏里拉拉丝芝士。","step_en":"Slice 低脂高钙纯牛奶/低脂干酪 thinly, sprinkle a light layer of mozzarella cheese on the base.","step_tl":"Hiwain ang 低脂高钙纯牛奶/低脂干酪, lagyan ng cheese sa ibabaw."},{"zone":"C","step_zh":"洗净高山天然鲜菌菇切小块，用厨房纸充分吸干多余水分防止塌陷；烤箱提前预热至200°C。","step_en":"Wash and dice 高山天然鲜菌菇, preheat oven to 200°C.","step_tl":"Hugasan ang 高山天然鲜菌菇, i-preheat ang oven sa 200°C."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将低脂高钙纯牛奶/低脂干酪片和脱去水分的高山天然鲜菌菇块美观、均匀地铺满在披萨饼面上","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 在最上面再厚厚地撒上一层诱人的马苏里拉拉丝芝士封层","time_seconds":30},{"step_zh":"[烤箱200°C/Oven] 迅速送入预热好的烤箱中层，设置上下火200°C安全烘烤约15分钟","time_seconds":900},{"step_zh":"[常温/Room Temp] 密切观察表面芝士完全融化并呈现金黄微焦状后取出，滚刀切成扇形拉丝食用","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8f57f81e-bb4e-47ad-94cc-40313979f873', '非油炸越式空气春卷', 'southeast_asian', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g天然粗粮黑小麦/综合高蛋白表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 天然粗粮黑小麦/综合高蛋白, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 天然粗粮黑小麦/综合高蛋白, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g天然粗粮黑小麦/综合高蛋白，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在天然粗粮黑小麦/综合高蛋白表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与天然粗粮黑小麦/综合高蛋白装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('1c0672c7-cbab-46c2-a228-49b16d266a6c', '高钙少油南洋炒蛋', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0b99f8a5-ed95-47d9-a883-99ae44440d8e', '高蛋白手工鱼丸汤', 'southeast_asian', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将深海高蛋白鲜鱼洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 深海高蛋白鲜鱼, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 深海高蛋白鲜鱼, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的深海高蛋白鲜鱼和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('16c31413-7b13-4ebb-9154-e16b8b3be1cf', '低脂黄咖喱鸡腿肉块', 'southeast_asian', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成3cm大块，加入10ml青柠汁抓匀去除腥味。","step_en":"Cut 300g of 农家散养清远鸡肉 into 3cm chunks, mix with 10ml lime juice.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 sa 3cm, haluan ng 10ml lime juice."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切块洗净备用。","step_en":"Cut and wash 150g of 四季时鲜杂蔬拼盘.","step_tl":"Hiwain at hugasan ang 150g ng 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备50g冬阴功酱/绿咖喱酱，200ml椰浆，1根香茅(拍碎)，2片柠檬叶。","step_en":"Prepare 50g curry paste, 200ml coconut milk, 1 bruised lemongrass, 2 kaffir lime leaves.","step_tl":"Ihanda ang 50g curry paste, 200ml coconut milk, 1 tanglad, 2 dahon ng dayap."}]}'::jsonb, '{"steps":[{"step_zh":"[中小火/Med-Low Heat] 锅中加10ml油，放入50g咖喱酱和香茅，小火慢炒60秒炒出红油香味。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 倒入200ml椰浆和100ml清水，大火煮沸。","time_seconds":120},{"step_zh":"[中火/Medium Heat] 放入300g农家散养清远鸡肉和柠檬叶，加盖中小火炖煮10分钟。","time_seconds":600},{"step_zh":"[中大火/Med-High Heat] 加入150g四季时鲜杂蔬拼盘继续炖煮3分钟，临出锅加5ml鱼露提鲜。","time_seconds":180}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a1cbe296-e2c8-4ed4-af81-21ed86a2f81a', '低脂鲜蔬越南纸卷', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g天然粗粮黑小麦/综合高蛋白表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 天然粗粮黑小麦/综合高蛋白, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 天然粗粮黑小麦/综合高蛋白, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g天然粗粮黑小麦/综合高蛋白，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在天然粗粮黑小麦/综合高蛋白表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与天然粗粮黑小麦/综合高蛋白装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('342a37dd-4775-497a-a0db-20bed72ca989', '滋补慢熬五谷八宝粥', 'jiangnan', '{default}', '{pregnancy}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和天然粗粮黑小麦/综合高蛋白迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e0ad1c89-6a10-4f1e-bcd0-af420ec651b5', '鲜蔬炒粿条', 'southeast_asian', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e9fbd7c9-ad0d-45a4-9542-02caded42243', '鲜蔬青椒肉丝', 'sichuan', '{spicy}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6f1c0919-ae44-44f2-85ec-acaaa40ca77d', '低糖糙米三角饭团', 'jiangnan', '{sweet}', '{detox}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d81951c9-89d9-4878-8845-424887711420', '高蛋白金枪鱼拌沙拉', 'western', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将150g的有机生鲜绿叶蔬菜彻底清洗干净，特别是生蔬菜必须在净水中泡10分钟，最后用脱水机彻底甩干水分。","step_en":"Wash 150g 有机生鲜绿叶蔬菜 thoroughly, soak greens in cold water, spin dry completely.","step_tl":"Hugasan ang 有机生鲜绿叶蔬菜, ibabad sa malamig na tubig, patuyuin."},{"zone":"B","step_zh":"处理150g的深海高蛋白鲜鱼主料（若非即食肉类则应提前用水煮或低油煎熟），将其切成小块或手撕成小片。","step_en":"Prepare 150g 深海高蛋白鲜鱼 (boil or sear if meat), cut or shred.","step_tl":"Ihanda ang 深海高蛋白鲜鱼, hiwain o punitin."},{"zone":"C","step_zh":"调配低卡油醋汁：30ml橄榄油、10ml纯果醋、5g蜂蜜、2g现磨粗粒黑胡椒及3g海盐混合摇匀至乳化。","step_en":"Mix vinaigrette: 3tbsp olive oil, 1tbsp vinegar, honey, pepper and salt.","step_tl":"Gawin ang sauce: oil, vinegar, honey, asin, paminta."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 取一个有深度的干净大沙拉碗，将沥干水分的爽翠有机生鲜绿叶蔬菜作为最下层积底平铺","time_seconds":30},{"step_zh":"[常温/Room Temp] 在铺好的蔬菜层上整齐地放上准备好的深海高蛋白鲜鱼。此时可依据喜好点缀小番茄或10g坚果碎补充营养","time_seconds":30},{"step_zh":"[常温/Room Temp] 食用前一分钟才均匀地淋上充分乳化调好的油醋沙拉汁，可使用沙拉夹稍微低手翻拌入味","time_seconds":30},{"step_zh":"[常温/Room Temp] 摆盘装面，若准备有全麦低脂面包丁则应最后撒上以长久保持其酥脆口感","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('64822d4d-d9b1-402a-914b-c9be51a1a9fe', '无糖简易提拉米苏', 'western', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a9a45f5f-90cd-48f6-87d2-3a7ad4cd7e68', '低脂纯芝麻酱烧饼', 'jiangnan', '{spicy}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('cb54d7da-a4a1-44d4-94c4-017f1d655d9b', '低卡白灼有机生菜', 'cantonese', '{light}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('3c2b3112-dbfe-439c-8145-2f9181ea8517', '低脂培根鲜奶蘑菇面', 'western', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将有机精选瘦猪肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 有机精选瘦猪肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将高山天然鲜菌菇洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 高山天然鲜菌菇.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 高山天然鲜菌菇."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的有机精选瘦猪肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回有机精选瘦猪肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7e1025cc-25a6-4d78-8568-3ac5282366d2', '高蛋白低卡沙嗲鸡串', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('20ca4e39-1951-49ea-9a48-9af7ebc49106', '无糖无油咕噜肉', 'cantonese', '{sweet}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('41e21336-4d41-46f2-aeac-587b60ba1e7b', '少油低脂平底锅生煎', 'jiangnan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备发面或饺子皮，将天然粗粮黑小麦/综合高蛋白剁成细碎肉馅，加入10ml葱姜水顺时针搅拌上劲。","step_en":"Prepare dough, mince 天然粗粮黑小麦/综合高蛋白 and stir in ginger water to make filling.","step_tl":"Ihanda ang masa, tadtarin ang 天然粗粮黑小麦/综合高蛋白 at haluin ng tubig luya."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切碎，稍加盐腌制后挤干水分，与肉馅混合调味，包成包子或饺子。","step_en":"Chop 四季时鲜杂蔬拼盘, squeeze out water, mix with meat filling and wrap.","step_tl":"Tadtarin ang 四季时鲜杂蔬拼盘, pigain, haluin sa karne at balutin."},{"zone":"C","step_zh":"准备一小碗冷水和一撮黑芝麻、香葱末备用。","step_en":"Prepare a small bowl of cold water, some black sesame and chopped scallions.","step_tl":"Ihanda ang tubig at sesame."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 平底锅加5ml食用油烧热，将包好的面点底部朝下放入，煎约2分钟至底部微黄","time_seconds":120},{"step_zh":"[大火/High Heat] 顺锅边倒入清水，水量没过底部约三分之一，立即盖紧锅盖","time_seconds":10},{"step_zh":"[中火/Medium Heat] 保持中火水煎约8-10分钟，听到锅内水分烧干，发出“滋啦”声响即可","time_seconds":540},{"step_zh":"[小火/Low Heat] 开盖，撒上提前准备的黑芝麻和葱花，小火再煎1分钟将底部煎脆出锅","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('ea2468da-be1d-4a54-b4cf-ef2c506f8e8b', '少油低卡泰式炒米河粉', 'southeast_asian', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('9457060e-683f-4583-9815-057c01eda89d', '高蛋白蚂蚁上树', 'sichuan', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('31aa2266-66be-422d-b1ae-cc7e77daed65', '减糖糖醋烧排骨', 'cantonese', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('121c8803-0b6d-4780-bfca-5973921ced3f', '孜然非油炸土豆片', 'sichuan', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g生态黄心小土豆/紫薯清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 生态黄心小土豆/紫薯 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 生态黄心小土豆/紫薯 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g生态黄心小土豆/紫薯，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('fcac2a77-fe5d-4a51-b47c-3b649404c4c7', '高蛋白香煎比目鱼', 'western', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g深海高蛋白鲜鱼表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 深海高蛋白鲜鱼, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 深海高蛋白鲜鱼, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g深海高蛋白鲜鱼，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在深海高蛋白鲜鱼表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与深海高蛋白鲜鱼装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('452e337f-f92f-4308-8c4f-6bda1fdb8946', '红枣麦片汤', 'jiangnan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 天然粗粮黑小麦/综合高蛋白, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 天然粗粮黑小麦/综合高蛋白, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的天然粗粮黑小麦/综合高蛋白和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d073b489-fac6-4d9b-a624-e08aac3c0ced', '低脂素馅速冻煎饺', 'jiangnan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备发面或饺子皮，将天然粗粮黑小麦/综合高蛋白剁成细碎肉馅，加入10ml葱姜水顺时针搅拌上劲。","step_en":"Prepare dough, mince 天然粗粮黑小麦/综合高蛋白 and stir in ginger water to make filling.","step_tl":"Ihanda ang masa, tadtarin ang 天然粗粮黑小麦/综合高蛋白 at haluin ng tubig luya."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切碎，稍加盐腌制后挤干水分，与肉馅混合调味，包成包子或饺子。","step_en":"Chop 四季时鲜杂蔬拼盘, squeeze out water, mix with meat filling and wrap.","step_tl":"Tadtarin ang 四季时鲜杂蔬拼盘, pigain, haluin sa karne at balutin."},{"zone":"C","step_zh":"准备一小碗冷水和一撮黑芝麻、香葱末备用。","step_en":"Prepare a small bowl of cold water, some black sesame and chopped scallions.","step_tl":"Ihanda ang tubig at sesame."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 平底锅加5ml食用油烧热，将包好的面点底部朝下放入，煎约2分钟至底部微黄","time_seconds":120},{"step_zh":"[大火/High Heat] 顺锅边倒入清水，水量没过底部约三分之一，立即盖紧锅盖","time_seconds":10},{"step_zh":"[中火/Medium Heat] 保持中火水煎约8-10分钟，听到锅内水分烧干，发出“滋啦”声响即可","time_seconds":540},{"step_zh":"[小火/Low Heat] 开盖，撒上提前准备的黑芝麻和葱花，小火再煎1分钟将底部煎脆出锅","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7e98dba6-cb3b-4079-b247-59ec7872e177', '家常低油水煮肉片', 'sichuan', '{light}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d71f0b68-1961-41d8-a93f-0ac1d24eb7b9', '新鲜大葱手工馄饨', 'jiangnan', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g紫皮鲜洋葱/大葱清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 紫皮鲜洋葱/大葱 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 紫皮鲜洋葱/大葱 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g紫皮鲜洋葱/大葱，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6f2c3b2c-9aee-4ab1-bab5-639ebdad5661', '葱爆瘦羊肉', 'sichuan', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g紫皮鲜洋葱/大葱清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 紫皮鲜洋葱/大葱 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 紫皮鲜洋葱/大葱 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g紫皮鲜洋葱/大葱，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('3c3e00f9-8a39-4365-9a75-740d56ad7d0c', '高钙番茄炒蛋', 'sichuan', '{sour}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g自然熟有机大番茄清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 自然熟有机大番茄 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 自然熟有机大番茄 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g自然熟有机大番茄，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('3d6f8a34-e636-45c6-912a-ec332d4796d9', '原味白斩鸡', 'sichuan', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('e6acff32-0310-46e4-8a78-8dc5506a3899', '无油烤箱版酥脆烤鸡腿肉', 'western', '{light}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g的农家散养清远鸡肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 农家散养清远鸡肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 农家散养清远鸡肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的农家散养清远鸡肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将农家散养清远鸡肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的农家散养清远鸡肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('11a00492-f368-47b4-a35c-5070726fd1a5', '鲜香少油泰式黄咖喱虾', 'southeast_asian', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成3cm大块，加入10ml青柠汁抓匀去除腥味。","step_en":"Cut 300g of 深海白对虾/活虾 into 3cm chunks, mix with 10ml lime juice.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 sa 3cm, haluan ng 10ml lime juice."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切块洗净备用。","step_en":"Cut and wash 150g of 四季时鲜杂蔬拼盘.","step_tl":"Hiwain at hugasan ang 150g ng 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备50g冬阴功酱/绿咖喱酱，200ml椰浆，1根香茅(拍碎)，2片柠檬叶。","step_en":"Prepare 50g curry paste, 200ml coconut milk, 1 bruised lemongrass, 2 kaffir lime leaves.","step_tl":"Ihanda ang 50g curry paste, 200ml coconut milk, 1 tanglad, 2 dahon ng dayap."}]}'::jsonb, '{"steps":[{"step_zh":"[中小火/Med-Low Heat] 锅中加10ml油，放入50g咖喱酱和香茅，小火慢炒60秒炒出红油香味。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 倒入200ml椰浆和100ml清水，大火煮沸。","time_seconds":120},{"step_zh":"[中火/Medium Heat] 放入300g深海白对虾/活虾和柠檬叶，加盖中小火炖煮10分钟。","time_seconds":600},{"step_zh":"[中大火/Med-High Heat] 加入150g四季时鲜杂蔬拼盘继续炖煮3分钟，临出锅加5ml鱼露提鲜。","time_seconds":180}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8d73f814-41cc-40d6-9d82-0ca47b418404', '爽口凉拌黑木耳', 'sichuan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g高山天然鲜菌菇清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 高山天然鲜菌菇 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 高山天然鲜菌菇 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g高山天然鲜菌菇，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('56b672db-d854-4f87-b49e-7ea6403cb733', '少油宫保鸡丁', 'sichuan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('28ebf649-8406-4475-8842-7f77480bacf1', '少油孜然鲜羊肉', 'sichuan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c35feabb-2863-41be-98a5-7f703dea4880', '滋补萝卜牛腩清汤', 'cantonese', '{light}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 高品质原切牛肉/瘦猪颈肉, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 高品质原切牛肉/瘦猪颈肉, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将鲜甜白萝卜/新西兰胡萝卜切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 鲜甜白萝卜/新西兰胡萝卜 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 鲜甜白萝卜/新西兰胡萝卜, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的高品质原切牛肉/瘦猪颈肉和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的鲜甜白萝卜/新西兰胡萝卜块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('eef4d35a-4877-4170-9fe0-0a8806e12cd0', '低热量椰香绿咖喱鸡', 'southeast_asian', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成3cm大块，加入10ml青柠汁抓匀去除腥味。","step_en":"Cut 300g of 农家散养清远鸡肉 into 3cm chunks, mix with 10ml lime juice.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 sa 3cm, haluan ng 10ml lime juice."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切块洗净备用。","step_en":"Cut and wash 150g of 四季时鲜杂蔬拼盘.","step_tl":"Hiwain at hugasan ang 150g ng 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备50g冬阴功酱/绿咖喱酱，200ml椰浆，1根香茅(拍碎)，2片柠檬叶。","step_en":"Prepare 50g curry paste, 200ml coconut milk, 1 bruised lemongrass, 2 kaffir lime leaves.","step_tl":"Ihanda ang 50g curry paste, 200ml coconut milk, 1 tanglad, 2 dahon ng dayap."}]}'::jsonb, '{"steps":[{"step_zh":"[中小火/Med-Low Heat] 锅中加10ml油，放入50g咖喱酱和香茅，小火慢炒60秒炒出红油香味。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 倒入200ml椰浆和100ml清水，大火煮沸。","time_seconds":120},{"step_zh":"[中火/Medium Heat] 放入300g农家散养清远鸡肉和柠檬叶，加盖中小火炖煮10分钟。","time_seconds":600},{"step_zh":"[中大火/Med-High Heat] 加入150g四季时鲜杂蔬拼盘继续炖煮3分钟，临出锅加5ml鱼露提鲜。","time_seconds":180}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('60406583-4030-4b4e-b922-005c6a45e0fc', '富含Omega3香煎三文鱼', 'western', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g深海高蛋白鲜鱼表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 深海高蛋白鲜鱼, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 深海高蛋白鲜鱼, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g深海高蛋白鲜鱼，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在深海高蛋白鲜鱼表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与深海高蛋白鲜鱼装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f514ab8e-de90-441b-a08b-1cdfc49ec070', '减糖泰式甜辣虾', 'southeast_asian', '{spicy}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('016372a4-16f2-4e5d-9dd8-73aed1a7b7f4', '低脂蜜汁叉烧瘦肉', 'cantonese', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a96e5015-37ac-4379-953b-1cfe32abee70', '低脂粗粮腊味饭', 'cantonese', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6a9736b0-8f7c-45e0-a6c0-887339c1bfe7', '高维C新鲜水果沙拉', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将150g的有机生鲜绿叶蔬菜彻底清洗干净，特别是生蔬菜必须在净水中泡10分钟，最后用脱水机彻底甩干水分。","step_en":"Wash 150g 有机生鲜绿叶蔬菜 thoroughly, soak greens in cold water, spin dry completely.","step_tl":"Hugasan ang 有机生鲜绿叶蔬菜, ibabad sa malamig na tubig, patuyuin."},{"zone":"B","step_zh":"处理150g的天然粗粮黑小麦/综合高蛋白主料（若非即食肉类则应提前用水煮或低油煎熟），将其切成小块或手撕成小片。","step_en":"Prepare 150g 天然粗粮黑小麦/综合高蛋白 (boil or sear if meat), cut or shred.","step_tl":"Ihanda ang 天然粗粮黑小麦/综合高蛋白, hiwain o punitin."},{"zone":"C","step_zh":"调配低卡油醋汁：30ml橄榄油、10ml纯果醋、5g蜂蜜、2g现磨粗粒黑胡椒及3g海盐混合摇匀至乳化。","step_en":"Mix vinaigrette: 3tbsp olive oil, 1tbsp vinegar, honey, pepper and salt.","step_tl":"Gawin ang sauce: oil, vinegar, honey, asin, paminta."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 取一个有深度的干净大沙拉碗，将沥干水分的爽翠有机生鲜绿叶蔬菜作为最下层积底平铺","time_seconds":30},{"step_zh":"[常温/Room Temp] 在铺好的蔬菜层上整齐地放上准备好的天然粗粮黑小麦/综合高蛋白。此时可依据喜好点缀小番茄或10g坚果碎补充营养","time_seconds":30},{"step_zh":"[常温/Room Temp] 食用前一分钟才均匀地淋上充分乳化调好的油醋沙拉汁，可使用沙拉夹稍微低手翻拌入味","time_seconds":30},{"step_zh":"[常温/Room Temp] 摆盘装面，若准备有全麦低脂面包丁则应最后撒上以长久保持其酥脆口感","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8dd3d551-f973-4a47-a26c-79f2f5433947', '全麦低卡玛格丽特披萨', 'western', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备一张发好的披萨饼底（也可用低脂墨西哥卷饼代替），在其表面均匀平涂一层番茄披萨底酱。","step_en":"Prepare a pizza crust (or tortilla), spread tomato pizza sauce evenly.","step_tl":"Ihanda ang pizza crust, lagyan ng tomato sauce."},{"zone":"B","step_zh":"将主食材天然粗粮黑小麦/综合高蛋白切成均匀薄片或小块，在底盘薄薄先撒上一层马苏里拉拉丝芝士。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 thinly, sprinkle a light layer of mozzarella cheese on the base.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, lagyan ng cheese sa ibabaw."},{"zone":"C","step_zh":"洗净四季时鲜杂蔬拼盘切小块，用厨房纸充分吸干多余水分防止塌陷；烤箱提前预热至200°C。","step_en":"Wash and dice 四季时鲜杂蔬拼盘, preheat oven to 200°C.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, i-preheat ang oven sa 200°C."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将天然粗粮黑小麦/综合高蛋白片和脱去水分的四季时鲜杂蔬拼盘块美观、均匀地铺满在披萨饼面上","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 在最上面再厚厚地撒上一层诱人的马苏里拉拉丝芝士封层","time_seconds":30},{"step_zh":"[烤箱200°C/Oven] 迅速送入预热好的烤箱中层，设置上下火200°C安全烘烤约15分钟","time_seconds":900},{"step_zh":"[常温/Room Temp] 密切观察表面芝士完全融化并呈现金黄微焦状后取出，滚刀切成扇形拉丝食用","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('0e95d96e-1b6e-4fe7-a3fb-21f0765f2153', '非油炸香兰叶鲜嫩烤鸡肉', 'southeast_asian', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g的农家散养清远鸡肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 农家散养清远鸡肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 农家散养清远鸡肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的农家散养清远鸡肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将农家散养清远鸡肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的农家散养清远鸡肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6f5aaa2b-8e1c-4ba8-af0d-6d8346699a89', '鲜辣炒花蛤', 'sichuan', '{spicy}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g优质海鲜干贝类切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 优质海鲜干贝类 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 优质海鲜干贝类 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的优质海鲜干贝类，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的优质海鲜干贝类回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('92105a76-5de3-4548-9ea0-251835531f03', '无油排骨汤米粉', 'cantonese', '{light}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 高品质原切牛肉/瘦猪颈肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 高品质原切牛肉/瘦猪颈肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的高品质原切牛肉/瘦猪颈肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回高品质原切牛肉/瘦猪颈肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('eb20946e-ec26-4cb8-8586-c7fe257fbc2b', '低脂泰式凉拌魔芋粉', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('379b86f6-348e-48c7-a9d4-cd4ce1ec870b', '低脂鲜蔬肉丝炒粉', 'jiangnan', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将有机精选瘦猪肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 有机精选瘦猪肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的有机精选瘦猪肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回有机精选瘦猪肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a7b38fea-a7dc-4513-9a86-1064cc921df9', '高蛋白柠香清蒸海鱼', 'southeast_asian', '{light}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用500ml清水清洗300g深海高蛋白鲜鱼，并且用厨房用纸彻底擦干水分。","step_en":"Wash 300g of 深海高蛋白鲜鱼 with 500ml water, dry completely with paper towels.","step_tl":"Hugasan ang 300g na 深海高蛋白鲜鱼 gamit ang 500ml na tubig, patuyuin nang maigi."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，平铺在蒸盘底部作为垫底。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, spread evenly at the bottom of the plate.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa habang 5cm, ilatag sa plato."},{"zone":"C","step_zh":"切20g极细的葱丝和10g姜丝，在200ml冰水中浸泡5分钟备用。","step_en":"Julienne 20g scallion and 10g ginger finely, soak in 200ml ice water for 5 mins.","step_tl":"Hiwain nang pino ang 20g sibuyas at 10g luya, ibabad sa 200ml yelo at tubig ng 5 minuto."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 蒸锅加1500ml清水，烧至完全沸腾（约5分钟），放入蒸架","time_seconds":300},{"step_zh":"[大火/High Heat] 放入装有深海高蛋白鲜鱼的蒸盘，加盖准时大火蒸制8分钟","time_seconds":480},{"step_zh":"[小火/Low Heat] 关小火出锅，立刻倒掉盘中多余的腥水，均匀铺上沥干水分的20g葱姜丝","time_seconds":30},{"step_zh":"[大火/High Heat] 另起锅烧30ml食用油至冒烟（约45秒），均匀淋在葱姜丝上激发出香味，再沿盘边缘倒入45ml蒸鱼酱油","time_seconds":45}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c75766b7-d3b4-4671-9b7c-55fabb7bc5ef', '低钠橄榄葱油拌面', 'jiangnan', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将紫皮鲜洋葱/大葱洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 紫皮鲜洋葱/大葱.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 紫皮鲜洋葱/大葱."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('464390b4-836c-45e9-8570-33e79f805e3d', '红茶慢熬五香鹌鹑蛋', 'jiangnan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('382df7d9-200d-4fba-9468-f2943f97fb84', '全麦少油葱油饼', 'jiangnan', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g紫皮鲜洋葱/大葱洗净切碎备用。","step_en":"Wash and chop 100g of 紫皮鲜洋葱/大葱.","step_tl":"Hugasan at tadtarin ang 100g na 紫皮鲜洋葱/大葱."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入紫皮鲜洋葱/大葱，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2349bf29-c564-47c6-a3be-485ad5175b4b', '滋补低脂冬阴功海鲜汤', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将优质海鲜干贝类洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 优质海鲜干贝类, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 优质海鲜干贝类, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的优质海鲜干贝类和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('72d044b6-4a30-4d0e-9fb2-8850467774a4', '无水低糖黄油曲奇', 'western', '{sweet}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('21a0f25a-0ca4-430a-b786-edf35111882f', '高钙纯奶香小馒头', 'jiangnan', '{sweet}', '{pregnancy}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g低脂高钙纯牛奶/低脂干酪切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 低脂高钙纯牛奶/低脂干酪 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 低脂高钙纯牛奶/低脂干酪 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的低脂高钙纯牛奶/低脂干酪，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的低脂高钙纯牛奶/低脂干酪回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('04ec8715-b5b3-4bd8-9393-246924f3b7df', '无糖纯黑芝麻糊', 'jiangnan', '{spicy}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成3cm见方的块，放入800ml冷水锅中，大火烧开焯水3分钟，捞出洗净血沫。","step_en":"Cut 300g of 天然粗粮黑小麦/综合高蛋白 into 3cm cubes, place in 800ml cold water, boil for 3 mins and rinse.","step_tl":"Hiwain ang 300g na 天然粗粮黑小麦/综合高蛋白 sa 3cm, ilagay sa 800ml malamig na tubig, pakuluan ng 3 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成4cm的滚刀块备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 4cm chunks.","step_tl":"Hiwain ang 150g na 四季时鲜杂蔬拼盘 sa 4cm na tipak."},{"zone":"C","step_zh":"准备15g大料（八角2颗、香叶3片、桂皮1小块）及20g葱姜蒜。","step_en":"Prepare 15g spices (2 star anise, 3 bay leaves, 1 cinnamon) and 20g aromatics.","step_tl":"Ihanda ang 15g pampalasa at 20g sibuyas, luya, bawang."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 热锅下15ml食用油，烧热后放入焯水后的天然粗粮黑小麦/综合高蛋白，微煎2分钟至表面微焦黄","time_seconds":120},{"step_zh":"[大火转小火/High to Low] 加入800ml沸水及15g香辛料，大火烧开后转最小火加盖慢炖40分钟","time_seconds":2400},{"step_zh":"[小火/Low Heat] 加入切好的150g四季时鲜杂蔬拼盘，继续加盖焖煮20分钟至软糯","time_seconds":1200},{"step_zh":"[大火/High Heat] 开大火收浓汤汁（约5分钟），加入3g盐调味后出锅","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2bde4781-4004-4d61-8ccf-61114612d0fe', '不加糖印尼酱烤鸡', 'southeast_asian', '{sweet}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g的农家散养清远鸡肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 农家散养清远鸡肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 农家散养清远鸡肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的农家散养清远鸡肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将农家散养清远鸡肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的农家散养清远鸡肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7bf70648-67ea-4092-9488-b43654522324', '无糖脱脂港式热奶茶', 'southeast_asian', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g低脂高钙纯牛奶/低脂干酪切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 低脂高钙纯牛奶/低脂干酪 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 低脂高钙纯牛奶/低脂干酪 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的低脂高钙纯牛奶/低脂干酪，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的低脂高钙纯牛奶/低脂干酪回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('cd7eafb1-e9bb-4046-ac3a-b310fade9d83', '全麦越式法棍三明治', 'southeast_asian', '{default}', '{detox}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将2片全麦面包/汉堡胚从中间切开，放入吐司炉或平底锅微微烘烤至表面微焦酥脆。","step_en":"Toast bread or burger buns until slightly crispy on the surface.","step_tl":"I-toast ang tinapay hanggang maging crispy."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白处理熟透（可香煎、微波加热或水煮断生），并单独煎制一个太阳蛋备用。","step_en":"Cook/sear the 天然粗粮黑小麦/综合高蛋白 slices, and fry a sunny-side-up egg.","step_tl":"Lutuin ang 天然粗粮黑小麦/综合高蛋白 at magprito ng itlog."},{"zone":"C","step_zh":"仔细洗净并用厨房纸擦干四季时鲜杂蔬拼盘，切几片新鲜熟番茄和爽脆洋葱圈用作解腻内馅。","step_en":"Wash and dry 四季时鲜杂蔬拼盘, slice tomatoes and onions for filling.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, hiwain ang kamatis at sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[常温/Room Temp] 铺平一片烘烤好的面包/汉堡底胚，在接触面均匀涂抹10g沙拉酱或5g低脂黄油保护面包","time_seconds":30},{"step_zh":"[常温/Room Temp] 依次叠加上一层平铺的四季时鲜杂蔬拼盘、煎熟且沥干油脂的天然粗粮黑小麦/综合高蛋白、清爽的番茄洋葱片及荷包蛋","time_seconds":45},{"step_zh":"[常温/Room Temp] 根据喜好面上加覆一片低脂芝士，最后盖上另一片面包顶胚","time_seconds":15},{"step_zh":"[中火/Medium Heat] （可选）用食品防油纸或保鲜膜紧紧包裹定型，然后从中间一刀对半切开方便大口食用","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2c611939-9523-4abc-9027-b4ff94108797', '红烧深海带鱼', 'sichuan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g深海高蛋白鲜鱼切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海高蛋白鲜鱼 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海高蛋白鲜鱼 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海高蛋白鲜鱼，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海高蛋白鲜鱼回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b8877295-6990-4738-abae-6a04f912dce0', '低脂蒜香黄油全麦法棍', 'western', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机香辛料(提香解腻)清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机香辛料(提香解腻) into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机香辛料(提香解腻) sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机香辛料(提香解腻)，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a815e99c-78e5-4004-a4c6-ea7996e76745', '低糖消暑珍多冰', 'southeast_asian', '{sweet}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7e092084-f272-487f-ad39-a38a1d42f354', '无油空气炸锅五花肉', 'cantonese', '{light}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g有机精选瘦猪肉表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 有机精选瘦猪肉, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 有机精选瘦猪肉, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g有机精选瘦猪肉，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在有机精选瘦猪肉表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与有机精选瘦猪肉装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8f671b65-7199-45d4-9416-5c524632de51', '高纤紫菜无糖肉松包饭', 'jiangnan', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将200g有机精选瘦猪肉切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 有机精选瘦猪肉 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 有机精选瘦猪肉 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g有机生鲜绿叶蔬菜洗净切碎备用。","step_en":"Wash and chop 100g of 有机生鲜绿叶蔬菜.","step_tl":"Hugasan at tadtarin ang 100g na 有机生鲜绿叶蔬菜."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入有机精选瘦猪肉，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入有机生鲜绿叶蔬菜，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('3da9526b-cc28-4733-b839-4fccffa57908', '高蛋白水煮嫩牛肉', 'sichuan', '{light}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('a11be273-6b6a-4c74-a5b7-7870504d973c', '高纤维素碗仔翅', 'cantonese', '{default}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('ca8f17c2-c865-4424-97aa-7df5282af431', '非油炸避风塘炒虾', 'cantonese', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('635d63e8-d63d-4fe7-8d17-7c06ccd08d3d', '高蛋白嫩滑豆腐脑', 'jiangnan', '{default}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将非转基因大豆/老豆腐洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 非转基因大豆/老豆腐, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 非转基因大豆/老豆腐, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的非转基因大豆/老豆腐和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('843c5d9d-10de-4071-a6f4-a5744a78de3f', '全麦意式番茄肉酱面', 'western', '{sour}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将高品质原切牛肉/瘦猪颈肉切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 高品质原切牛肉/瘦猪颈肉, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 高品质原切牛肉/瘦猪颈肉, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将自然熟有机大番茄洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 自然熟有机大番茄.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 自然熟有机大番茄."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的高品质原切牛肉/瘦猪颈肉滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回高品质原切牛肉/瘦猪颈肉煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('82038b99-89bb-472c-a270-f2b66c8f08f1', '清爽香菇油菜', 'sichuan', '{light}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7b69b2cf-decd-4b2d-af66-01e755c6aca2', '少油香煎鲜萝卜糕', 'southeast_asian', '{default}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g鲜甜白萝卜/新西兰胡萝卜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 鲜甜白萝卜/新西兰胡萝卜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 鲜甜白萝卜/新西兰胡萝卜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g鲜甜白萝卜/新西兰胡萝卜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('79e335d0-fb7d-4320-b255-7beac5ae2391', '少油脆底水煎包', 'jiangnan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备发面或饺子皮，将天然粗粮黑小麦/综合高蛋白剁成细碎肉馅，加入10ml葱姜水顺时针搅拌上劲。","step_en":"Prepare dough, mince 天然粗粮黑小麦/综合高蛋白 and stir in ginger water to make filling.","step_tl":"Ihanda ang masa, tadtarin ang 天然粗粮黑小麦/综合高蛋白 at haluin ng tubig luya."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切碎，稍加盐腌制后挤干水分，与肉馅混合调味，包成包子或饺子。","step_en":"Chop 四季时鲜杂蔬拼盘, squeeze out water, mix with meat filling and wrap.","step_tl":"Tadtarin ang 四季时鲜杂蔬拼盘, pigain, haluin sa karne at balutin."},{"zone":"C","step_zh":"准备一小碗冷水和一撮黑芝麻、香葱末备用。","step_en":"Prepare a small bowl of cold water, some black sesame and chopped scallions.","step_tl":"Ihanda ang tubig at sesame."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 平底锅加5ml食用油烧热，将包好的面点底部朝下放入，煎约2分钟至底部微黄","time_seconds":120},{"step_zh":"[大火/High Heat] 顺锅边倒入清水，水量没过底部约三分之一，立即盖紧锅盖","time_seconds":10},{"step_zh":"[中火/Medium Heat] 保持中火水煎约8-10分钟，听到锅内水分烧干，发出“滋啦”声响即可","time_seconds":540},{"step_zh":"[小火/Low Heat] 开盖，撒上提前准备的黑芝麻和葱花，小火再煎1分钟将底部煎脆出锅","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('8d8c2f4e-8ae4-4188-ab7c-0d4db332c42a', '全麦法式西多士', 'cantonese', '{default}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('73e77317-a262-4941-a525-b626aee52ee2', '低脂泰式海鲜魔芋汤', 'southeast_asian', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将优质海鲜干贝类洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 优质海鲜干贝类, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 优质海鲜干贝类, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的优质海鲜干贝类和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b7a0fb74-17a5-4f0a-a58c-7225aa5b8899', '清炒高蛋白虾仁', 'sichuan', '{light}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
