INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b9246e24-3d5e-4ce2-9ffe-1a9b40a9c8f1', '低脂咸蛋黄炒南瓜', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g可生食无菌土鸡蛋切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 可生食无菌土鸡蛋 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 可生食无菌土鸡蛋 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的可生食无菌土鸡蛋，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的可生食无菌土鸡蛋回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('ad3ead60-80ea-44a5-b241-aa8de1809dd0', '高维C蒜蓉新鲜西兰花', 'western', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('04e075a2-ee68-45bf-aded-9a26dd5e4df0', '低卡全麦烤箱披萨', 'western', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"准备一张发好的披萨饼底（也可用低脂墨西哥卷饼代替），在其表面均匀平涂一层番茄披萨底酱。","step_en":"Prepare a pizza crust (or tortilla), spread tomato pizza sauce evenly.","step_tl":"Ihanda ang pizza crust, lagyan ng tomato sauce."},{"zone":"B","step_zh":"将主食材天然粗粮黑小麦/综合高蛋白切成均匀薄片或小块，在底盘薄薄先撒上一层马苏里拉拉丝芝士。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 thinly, sprinkle a light layer of mozzarella cheese on the base.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, lagyan ng cheese sa ibabaw."},{"zone":"C","step_zh":"洗净四季时鲜杂蔬拼盘切小块，用厨房纸充分吸干多余水分防止塌陷；烤箱提前预热至200°C。","step_en":"Wash and dice 四季时鲜杂蔬拼盘, preheat oven to 200°C.","step_tl":"Hugasan ang 四季时鲜杂蔬拼盘, i-preheat ang oven sa 200°C."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将天然粗粮黑小麦/综合高蛋白片和脱去水分的四季时鲜杂蔬拼盘块美观、均匀地铺满在披萨饼面上","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 在最上面再厚厚地撒上一层诱人的马苏里拉拉丝芝士封层","time_seconds":30},{"step_zh":"[烤箱200°C/Oven] 迅速送入预热好的烤箱中层，设置上下火200°C安全烘烤约15分钟","time_seconds":900},{"step_zh":"[常温/Room Temp] 密切观察表面芝士完全融化并呈现金黄微焦状后取出，滚刀切成扇形拉丝食用","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2d471cc9-e98f-46c9-a4b4-28bc815d111b', '有机手撕包菜', 'sichuan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机生鲜绿叶蔬菜 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机生鲜绿叶蔬菜，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('cd3d8c5d-c14a-4d66-97f3-164873ff111d', '低脂纯瘦肉肉夹馍', 'jiangnan', '{default}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('83cfc182-0542-4649-b1fb-89db4e66bd6d', '高纤维蒜苔炒肉', 'sichuan', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g有机香辛料(提香解腻)清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 有机香辛料(提香解腻) into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 有机香辛料(提香解腻) sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g有机香辛料(提香解腻)，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('59779911-0226-46ea-91e7-bb9a6f40c537', '少油鱼香茄子煲', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g深海高蛋白鲜鱼切成3cm见方的块，放入800ml冷水锅中，大火烧开焯水3分钟，捞出洗净血沫。","step_en":"Cut 300g of 深海高蛋白鲜鱼 into 3cm cubes, place in 800ml cold water, boil for 3 mins and rinse.","step_tl":"Hiwain ang 300g na 深海高蛋白鲜鱼 sa 3cm, ilagay sa 800ml malamig na tubig, pakuluan ng 3 minuto."},{"zone":"B","step_zh":"将150g新鲜紫皮鲜茄子切成4cm的滚刀块备用。","step_en":"Cut 150g of 新鲜紫皮鲜茄子 into 4cm chunks.","step_tl":"Hiwain ang 150g na 新鲜紫皮鲜茄子 sa 4cm na tipak."},{"zone":"C","step_zh":"准备15g大料（八角2颗、香叶3片、桂皮1小块）及20g葱姜蒜。","step_en":"Prepare 15g spices (2 star anise, 3 bay leaves, 1 cinnamon) and 20g aromatics.","step_tl":"Ihanda ang 15g pampalasa at 20g sibuyas, luya, bawang."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 热锅下15ml食用油，烧热后放入焯水后的深海高蛋白鲜鱼，微煎2分钟至表面微焦黄","time_seconds":120},{"step_zh":"[大火转小火/High to Low] 加入800ml沸水及15g香辛料，大火烧开后转最小火加盖慢炖40分钟","time_seconds":2400},{"step_zh":"[小火/Low Heat] 加入切好的150g新鲜紫皮鲜茄子，继续加盖焖煮20分钟至软糯","time_seconds":1200},{"step_zh":"[大火/High Heat] 开大火收浓汤汁（约5分钟），加入3g盐调味后出锅","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('47e28a7b-8910-40d0-9cfe-125821301b4b', '减糖蜜汁烤猪肋排', 'western', '{sweet}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g的有机精选瘦猪肉表面划花刀帮助入味，用10ml生抽、5g耗油、5g蜂蜜和2g黑胡椒腌制至少2小时完全入味。","step_en":"Score 300g 有机精选瘦猪肉, marinate with soy sauce, oyster sauce, honey and pepper for 2 hours.","step_tl":"Hiwain ang 有机精选瘦猪肉, i-marinate sa toyo, oyster sauce, honey, at paminta."},{"zone":"B","step_zh":"将150g的四季时鲜杂蔬拼盘切成大小适中的块状，用5ml橄榄油和2g海盐在碗中抓拌均匀。","step_en":"Cut 150g 四季时鲜杂蔬拼盘 into chunks, toss with olive oil and sea salt.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, haluan ng olive oil at asin."},{"zone":"C","step_zh":"烤箱提前以200°C预热10分钟温度稳定，烤盘内提前铺上锡纸并刷5ml食用油以防粘连。","step_en":"Preheat oven to 200°C, line baking tray with foil and brush oil.","step_tl":"I-preheat ang oven sa 200°C, lagyan ng foil at mantika ang tray."}]}'::jsonb, '{"steps":[{"step_zh":"[烤箱200°C/Oven] 将腌好的有机精选瘦猪肉放在锡纸中心位置，送入烤箱中层首轮烤制20分钟","time_seconds":1200},{"step_zh":"[烤箱200°C/Oven] 戴防烫手套取出烤盘，将有机精选瘦猪肉彻底翻一个面，并在四周空隙处铺排上四季时鲜杂蔬拼盘","time_seconds":120},{"step_zh":"[烤箱200°C/Oven] 拿厨房硅胶刷在新翻的有机精选瘦猪肉表面再刷一层剩下的腌料汁（或蜂蜜水）光亮增色","time_seconds":60},{"step_zh":"[烤箱200°C/Oven] 送回烤箱继续烘烤10-15分钟逼出香气，观察表面起焦糖色即大功告成出炉","time_seconds":900}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f37b6149-5596-4027-ab55-1d23ab56f50a', '鲜蔬家常粗粮拌面', 'jiangnan', '{default}', '{detox}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2fe3ee4a-d762-47b5-9926-9f30e29dec52', '减糖甜酸肉段', 'sichuan', '{sour}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('49d34576-ef0a-41c3-89b4-292cb5cbb17d', '非油炸辣子鸡', 'sichuan', '{spicy}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g农家散养清远鸡肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 农家散养清远鸡肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 农家散养清远鸡肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的农家散养清远鸡肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的农家散养清远鸡肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('3f8491a7-a4f9-4a81-9b4a-1737efcbddbb', '非油炸椒盐鱿鱼圈', 'cantonese', '{spicy}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g深海高蛋白鲜鱼切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海高蛋白鲜鱼 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海高蛋白鲜鱼 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海高蛋白鲜鱼，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海高蛋白鲜鱼回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('c650d90f-6066-4f58-937d-83d89273d079', '低脂鲜蔬家庭版塔可', 'western', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('7b45ac9b-b2bf-4294-9d7f-8a4366f06a83', '低脂凉拌牛肉', 'sichuan', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('36c88c3d-1e84-4d61-bac3-deae04820b5d', '全麦法式煎吐司', 'western', '{default}', '{detox}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g天然粗粮黑小麦/综合高蛋白表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 天然粗粮黑小麦/综合高蛋白, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 天然粗粮黑小麦/综合高蛋白, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 四季时鲜杂蔬拼盘 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g天然粗粮黑小麦/综合高蛋白，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在天然粗粮黑小麦/综合高蛋白表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g四季时鲜杂蔬拼盘约90秒，与天然粗粮黑小麦/综合高蛋白装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b8cc0897-fb6d-42d0-8098-aaa251c89ada', '高纤十谷杂粮养生粥', 'jiangnan', '{default}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和天然粗粮黑小麦/综合高蛋白迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('90ab68a5-3388-411e-9088-ffb7ede90d21', '高蛋白鲜蔬黑椒肉', 'southeast_asian', '{spicy}', '{muscle_gain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5da2cfd7-9424-41eb-aecf-d63a3a9d73de', '少油福建健康炒饭', 'cantonese', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备300g隔夜冷藏米饭，用3ml食用油或清水在碗中提前抓散成颗粒状防粘。","step_en":"Prepare 300g leftover rice, break into grains with a little oil or water.","step_tl":"Ihanda ang 300g na kanin, paghiwalayin ang butil."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成约1cm见方的小丁；同时将四季时鲜杂蔬拼盘洗净也切成同等大小的碎丁保持口感统一。","step_en":"Dice 天然粗粮黑小麦/综合高蛋白 into 1cm cubes; wash and completely dice 四季时鲜杂蔬拼盘.","step_tl":"Tadtarin ang 天然粗粮黑小麦/综合高蛋白 at 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"碗中打散2个鸡蛋搅匀成蛋液，并备好提香的葱花。","step_en":"Beat 2 eggs evenly, prepare chopped scallions.","step_tl":"Batihin ang 2 itlog, ihanda ang sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧热炒锅倒入15ml食用油，倒入打散的鸡蛋液，快速炒熟盛出并略微切碎后备用","time_seconds":60},{"step_zh":"[中火/Medium Heat] 锅底补5ml底油，下入天然粗粮黑小麦/综合高蛋白丁煸炒至断生表面微缩，接着下入四季时鲜杂蔬拼盘丁炒出明香","time_seconds":120},{"step_zh":"[大火/High Heat] 倒入提前抓散的米饭，转大火快速持续翻炒按压，让每一粒米均匀受热","time_seconds":180},{"step_zh":"[大火/High Heat] 将炒好的鸡蛋倒回锅中，加入10ml生抽、2g盐和10g葱花，大火颠锅翻炒30秒产生锅气出炉","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('fc58a60c-d5e3-4fc2-8bbc-b681039b95f5', '低卡原味白灼虾', 'cantonese', '{light}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g深海白对虾/活虾切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 深海白对虾/活虾 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 深海白对虾/活虾 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的深海白对虾/活虾，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的深海白对虾/活虾回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('24531414-38b8-4d58-9276-f242db88e578', '无糖高纤全麦厚切软包', 'jiangnan', '{sweet}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将200g天然粗粮黑小麦/综合高蛋白切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 天然粗粮黑小麦/综合高蛋白 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 天然粗粮黑小麦/综合高蛋白 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g四季时鲜杂蔬拼盘洗净切碎备用。","step_en":"Wash and chop 100g of 四季时鲜杂蔬拼盘.","step_tl":"Hugasan at tadtarin ang 100g na 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入天然粗粮黑小麦/综合高蛋白，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入四季时鲜杂蔬拼盘，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('560292b3-2d60-48dc-bbfa-eb02ed5ece05', '牛油果太阳蛋全麦吐司', 'western', '{default}', '{detox}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g时令新鲜无公害水果清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 时令新鲜无公害水果 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 时令新鲜无公害水果 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g时令新鲜无公害水果，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('eb1ce389-d70a-4e3d-b302-1c8b7b8ac81f', '少油印尼风味炒饭', 'southeast_asian', '{default}', '{lose_weight}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"准备300g隔夜冷藏米饭，用3ml食用油或清水在碗中提前抓散成颗粒状防粘。","step_en":"Prepare 300g leftover rice, break into grains with a little oil or water.","step_tl":"Ihanda ang 300g na kanin, paghiwalayin ang butil."},{"zone":"B","step_zh":"将天然粗粮黑小麦/综合高蛋白切成约1cm见方的小丁；同时将四季时鲜杂蔬拼盘洗净也切成同等大小的碎丁保持口感统一。","step_en":"Dice 天然粗粮黑小麦/综合高蛋白 into 1cm cubes; wash and completely dice 四季时鲜杂蔬拼盘.","step_tl":"Tadtarin ang 天然粗粮黑小麦/综合高蛋白 at 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"碗中打散2个鸡蛋搅匀成蛋液，并备好提香的葱花。","step_en":"Beat 2 eggs evenly, prepare chopped scallions.","step_tl":"Batihin ang 2 itlog, ihanda ang sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧热炒锅倒入15ml食用油，倒入打散的鸡蛋液，快速炒熟盛出并略微切碎后备用","time_seconds":60},{"step_zh":"[中火/Medium Heat] 锅底补5ml底油，下入天然粗粮黑小麦/综合高蛋白丁煸炒至断生表面微缩，接着下入四季时鲜杂蔬拼盘丁炒出明香","time_seconds":120},{"step_zh":"[大火/High Heat] 倒入提前抓散的米饭，转大火快速持续翻炒按压，让每一粒米均匀受热","time_seconds":180},{"step_zh":"[大火/High Heat] 将炒好的鸡蛋倒回锅中，加入10ml生抽、2g盐和10g葱花，大火颠锅翻炒30秒产生锅气出炉","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('d6fc14e9-e41e-47e0-94d4-3e54e9b071e1', '低钠法式鲜洋葱汤', 'western', '{default}', '{maintain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 天然粗粮黑小麦/综合高蛋白, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 天然粗粮黑小麦/综合高蛋白, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将紫皮鲜洋葱/大葱切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 紫皮鲜洋葱/大葱 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 紫皮鲜洋葱/大葱, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的天然粗粮黑小麦/综合高蛋白和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的紫皮鲜洋葱/大葱块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('80ad1c52-187c-42c5-bb9b-46b85dca467a', '滋补养生肉骨茶', 'southeast_asian', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 有机精选瘦猪肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的有机精选瘦猪肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的有机精选瘦猪肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('3e55ff2a-be52-42a0-93e4-a989867f11ad', '高营养滑蛋炒牛肉', 'cantonese', '{default}', '{muscle_gain}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将300g高品质原切牛肉/瘦猪颈肉切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 高品质原切牛肉/瘦猪颈肉 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 高品质原切牛肉/瘦猪颈肉 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的高品质原切牛肉/瘦猪颈肉，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的高品质原切牛肉/瘦猪颈肉回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('90f5c833-2310-409f-bdf2-008320f8f93f', '纯椰奶冰淇淋', 'southeast_asian', '{sweet}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g低脂高钙纯牛奶/低脂干酪切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 低脂高钙纯牛奶/低脂干酪 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 低脂高钙纯牛奶/低脂干酪 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的低脂高钙纯牛奶/低脂干酪，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的低脂高钙纯牛奶/低脂干酪回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('01f0681a-6354-43ef-b500-7d053a7c02ec', '家常红烧豆腐', 'sichuan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g非转基因大豆/老豆腐切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 非转基因大豆/老豆腐 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 非转基因大豆/老豆腐 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的非转基因大豆/老豆腐，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的非转基因大豆/老豆腐回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6949377e-b2f7-441a-916a-6fe2255b1a30', '无油空气炸杂菜串', 'western', '{light}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g天然粗粮黑小麦/综合高蛋白表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 天然粗粮黑小麦/综合高蛋白, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 天然粗粮黑小麦/综合高蛋白, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g有机生鲜绿叶蔬菜切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 有机生鲜绿叶蔬菜 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 有机生鲜绿叶蔬菜 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g天然粗粮黑小麦/综合高蛋白，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在天然粗粮黑小麦/综合高蛋白表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g有机生鲜绿叶蔬菜约90秒，与天然粗粮黑小麦/综合高蛋白装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('b6e1faa3-075e-424e-a0fa-eacd7d4ddbb6', '无糖天然杨枝甘露', 'cantonese', '{sweet}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g天然粗粮黑小麦/综合高蛋白切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 天然粗粮黑小麦/综合高蛋白 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 天然粗粮黑小麦/综合高蛋白 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 四季时鲜杂蔬拼盘 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 四季时鲜杂蔬拼盘 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的天然粗粮黑小麦/综合高蛋白，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g四季时鲜杂蔬拼盘，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的天然粗粮黑小麦/综合高蛋白回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('5d35590e-6a5a-4fa3-b261-ef58829d0022', '杂蔬双鸡蛋煎饼果子', 'jiangnan', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将200g农家散养清远鸡肉切成细丝或小块，用2g盐和1g白胡椒粉腌制入味。","step_en":"Cut 200g of 农家散养清远鸡肉 into fine shreds or chunks, marinate with salt and white pepper.","step_tl":"Hiwain ang 200g na 农家散养清远鸡肉 nang pino, i-marinate sa asin at paminta."},{"zone":"B","step_zh":"将100g时令新鲜无公害水果洗净切碎备用。","step_en":"Wash and chop 100g of 时令新鲜无公害水果.","step_tl":"Hugasan at tadtarin ang 100g na 时令新鲜无公害水果."},{"zone":"C","step_zh":"准备好高汤或营养粥底500ml。","step_en":"Prepare 500ml broth or congee base.","step_tl":"Maghanda ng 500ml na sabaw o lugaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中倒入高汤/粥底烧开 (约3分钟)。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 加入农家散养清远鸡肉，迅速搅散煮至变色。","time_seconds":60},{"step_zh":"[小火/Low Heat] 加入时令新鲜无公害水果，略煮1分钟即可出锅。","time_seconds":60}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('73e5cbd2-8f55-415f-ae26-b2e1d75a1aa3', '营养鲜蔬罗宋汤', 'western', '{default}', '{maintain}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 天然粗粮黑小麦/综合高蛋白, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 天然粗粮黑小麦/综合高蛋白, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的天然粗粮黑小麦/综合高蛋白和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('6eb1692b-f589-463c-9e5c-c010ed3eca7d', '无糖黑芝麻养生汤圆', 'jiangnan', '{spicy}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白洗净，放入凉水锅中烧开焯水去除血沫，捞出用温水冲净残渣备用。","step_en":"Wash 天然粗粮黑小麦/综合高蛋白, blanch in boiling water to remove scum, rinse with warm water.","step_tl":"Hugasan at banlian ang 天然粗粮黑小麦/综合高蛋白, hugasan ng maligamgam na tubig."},{"zone":"B","step_zh":"将四季时鲜杂蔬拼盘切成滚刀块或厚片，保证慢炖不易散碎；再切两片生姜片去腥。","step_en":"Cut 四季时鲜杂蔬拼盘 into chunks or thick slices; prepare 2 ginger slices.","step_tl":"Hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."},{"zone":"C","step_zh":"准备煲汤辅料，如洗净泡发的红枣、枸杞或干贝等增加鲜甜味。","step_en":"Wash and soak dried scallops or red dates if available.","step_tl":"Hugasan at ibabad ang mga pampalasa."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 将焯好的天然粗粮黑小麦/综合高蛋白和姜片放入专用煲汤砂锅，加入至少1.5升过滤清水，开大火煮沸","time_seconds":600},{"step_zh":"[小火/Low Heat] 待水完全沸腾后，捞去表面浮沫，盖上锅盖，转小火慢炖1至1.5小时熬制底汤","time_seconds":3600},{"step_zh":"[小火/Low Heat] 取出锅盖放入切好的四季时鲜杂蔬拼盘块，继续盖盖慢炖30分钟让汤汁融入蔬菜清香","time_seconds":1800},{"step_zh":"[小火/Low Heat] 出锅前5分钟放入3g盐调味，切忌过早放盐以防肉排鲜味流失变柴","time_seconds":300}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('1e98692b-16c5-4486-a65a-3f09af8c232e', '高脂香煎鳕鱼配紫薯', 'western', '{default}', '{maintain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"用厨房纸将300g深海高蛋白鲜鱼表面水分彻底吸干，均匀撒上3g海盐和2g现磨黑胡椒腌制5分钟。","step_en":"Pat dry 300g of 深海高蛋白鲜鱼, season with 3g sea salt and 2g black pepper for 5 mins.","step_tl":"Patuyuin ang 300g ng 深海高蛋白鲜鱼, timplahan ng 3g asin at 2g paminta ng 5 minuto."},{"zone":"B","step_zh":"将150g生态黄心小土豆/紫薯切成5cm长段，加5ml橄榄油和1g盐拌匀备用。","step_en":"Cut 150g of 生态黄心小土豆/紫薯 into 5cm segments, toss with 5ml olive oil and 1g salt.","step_tl":"Hiwain ang 150g ng 生态黄心小土豆/紫薯 sa 5cm, haluan ng 5ml olive oil at 1g asin."},{"zone":"C","step_zh":"拍扁2瓣(10g)带皮大蒜，准备5g新鲜迷迭香和20g无盐黄油。","step_en":"Crush 10g garlic (skin on), prepare 5g fresh rosemary and 20g unsalted butter.","step_tl":"Durugin ang 10g bawang(may balat), ihanda ang 5g rosemary at 20g butter."}]}'::jsonb, '{"steps":[{"step_zh":"[中火/Medium Heat] 锅中加10ml橄榄油热锅至微隐冒烟，放入300g深海高蛋白鲜鱼，单面静置煎制180秒至形成美拉德焦化层。","time_seconds":180},{"step_zh":"[中火/Medium Heat] 翻面，立刻放入20g黄油、10g大蒜和5g迷迭香。","time_seconds":15},{"step_zh":"[中小火/Med-Low Heat] 倾斜煎锅，用勺子将融化的黄油不断淋在深海高蛋白鲜鱼表面(Basting)约60秒，盛出静置(Rest)3分钟。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 用锅中底油快速煎炒150g生态黄心小土豆/紫薯约90秒，与深海高蛋白鲜鱼装盘。","time_seconds":90}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('2797f93d-060f-49ed-b27e-84ae10375f1e', '少油全麦酱油炒面', 'jiangnan', '{salty}', '{lose_weight}', 'Autumn/Nourishing', '', '{"steps":[{"zone":"A","step_zh":"将天然粗粮黑小麦/综合高蛋白切薄片或均匀细丝，加入10ml生抽、2g盐和3g生粉抓拌腌制15分钟提味。","step_en":"Slice 天然粗粮黑小麦/综合高蛋白, marinate with soy sauce, salt, and cornstarch for 15 mins.","step_tl":"Hiwain ang 天然粗粮黑小麦/综合高蛋白, i-marinate ng 15 minuto."},{"zone":"B","step_zh":"准备150g面条/米粉，若是干粉需提前用温水泡软；同时将四季时鲜杂蔬拼盘洗净切成易于夹取的段状。","step_en":"Prepare noodles/rice noodles (soak if dry); wash and cut 四季时鲜杂蔬拼盘.","step_tl":"Ihanda ang noodles, hugasan at hiwain ang 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"切好10g葱段和15g蒜末，同时准备好鲜香的高汤或一壶开水（依汤面或炒面而定）。","step_en":"Chop scallions/garlic, prepare broth or boiling water.","step_tl":"Tadtarin ang bawang/sibuyas, ihanda ang sabaw."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 烧开一锅沸腾水，将面条/河粉下入焯烫至八成熟，迅速捞出过冷水沥干","time_seconds":300},{"step_zh":"[大火/High Heat] 炒锅烧热下油，下入腌制好的天然粗粮黑小麦/综合高蛋白滑炒至刚变色，立即盛出备用","time_seconds":90},{"step_zh":"[中大火/Med-High Heat] 原锅倒入高汤（如果是煮汤面）烧开，加入蔬菜并倒回天然粗粮黑小麦/综合高蛋白煮透；若是炒面则直接下配菜翻炒","time_seconds":240},{"step_zh":"[小火/Low Heat] 关火将汤料浇在底面上，或将炒好的粉面淋上5ml芝麻油拌匀装盘","time_seconds":30}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('501cdb06-fb6c-4684-9eab-cf6e83e39a70', '高蛋白红咖喱炖肉', 'southeast_asian', '{default}', '{muscle_gain}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将300g有机精选瘦猪肉切成3cm大块，加入10ml青柠汁抓匀去除腥味。","step_en":"Cut 300g of 有机精选瘦猪肉 into 3cm chunks, mix with 10ml lime juice.","step_tl":"Hiwain ang 300g ng 有机精选瘦猪肉 sa 3cm, haluan ng 10ml lime juice."},{"zone":"B","step_zh":"将150g四季时鲜杂蔬拼盘切块洗净备用。","step_en":"Cut and wash 150g of 四季时鲜杂蔬拼盘.","step_tl":"Hiwain at hugasan ang 150g ng 四季时鲜杂蔬拼盘."},{"zone":"C","step_zh":"准备50g冬阴功酱/绿咖喱酱，200ml椰浆，1根香茅(拍碎)，2片柠檬叶。","step_en":"Prepare 50g curry paste, 200ml coconut milk, 1 bruised lemongrass, 2 kaffir lime leaves.","step_tl":"Ihanda ang 50g curry paste, 200ml coconut milk, 1 tanglad, 2 dahon ng dayap."}]}'::jsonb, '{"steps":[{"step_zh":"[中小火/Med-Low Heat] 锅中加10ml油，放入50g咖喱酱和香茅，小火慢炒60秒炒出红油香味。","time_seconds":60},{"step_zh":"[中火/Medium Heat] 倒入200ml椰浆和100ml清水，大火煮沸。","time_seconds":120},{"step_zh":"[中火/Medium Heat] 放入300g有机精选瘦猪肉和柠檬叶，加盖中小火炖煮10分钟。","time_seconds":600},{"step_zh":"[中大火/Med-High Heat] 加入150g四季时鲜杂蔬拼盘继续炖煮3分钟，临出锅加5ml鱼露提鲜。","time_seconds":180}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('4c8c4af3-aabb-4b8e-823f-3c075df3b2dc', '高锌低脂番茄海鲜烩饭', 'western', '{sour}', '{lose_weight}', 'Spring/Damp-Clear', '', '{"steps":[{"zone":"A","step_zh":"将300g优质海鲜干贝类切成2mm厚薄片/段，加入10ml生抽和5g生粉，抓拌均匀腌制10分钟上浆。","step_en":"Slice 300g of 优质海鲜干贝类 into 2mm thickness, marinate with 10ml soy sauce and 5g cornstarch.","step_tl":"Hiwain ang 300g ng 优质海鲜干贝类 ng 2mm, i-marinate sa 10ml toyo at 5g cornstarch."},{"zone":"B","step_zh":"将150g自然熟有机大番茄清洗干净，切成4cm长的段备用。","step_en":"Wash and cut 150g of 自然熟有机大番茄 into 4cm lengths.","step_tl":"Hugasan at hiwain ang 150g ng 自然熟有机大番茄 sa habang 4cm."},{"zone":"C","step_zh":"将15g蒜和10g姜切成细末，15g葱切成葱花备用。","step_en":"Mince 15g garlic, 10g ginger, and chop 15g scallions.","step_tl":"Tadtarin ang 15g bawang, 10g luya, at hiwain ang 15g sibuyas."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 热锅加入30ml食用油烧至七成热，下300g腌制好的优质海鲜干贝类，快速滑炒45秒至肉膜变色，盛出备用","time_seconds":45},{"step_zh":"[中火/Medium Heat] 锅中留10ml底油，下入切好的15g蒜末和10g姜末，中火爆香30秒","time_seconds":30},{"step_zh":"[大火/High Heat] 下入150g自然熟有机大番茄，大火快速翻炒60秒至断生","time_seconds":60},{"step_zh":"[大火/High Heat] 将盛出的优质海鲜干贝类回锅，加入5ml生抽，大火颠锅翻炒20秒极速出锅","time_seconds":20}]}'::jsonb);
INSERT INTO dishes (id, title_zh, origin_cuisine, flavor_tags, health_benefit_tags, seasonal_tag, image_url, prep_steps_json, cook_steps_json) VALUES ('f3ee296b-4144-4ddc-bb27-eb673407014b', '高钙纯牛奶原味燕麦粥', 'jiangnan', '{sweet}', '{pregnancy}', 'All-Season/Balanced', '', '{"steps":[{"zone":"A","step_zh":"将大米淘洗干净，提前用3g食用油和2g盐腌制30分钟，以此法更容易煮出开花状态。","step_en":"Wash rice, marinate with a bit of oil and salt for 30 mins to soften.","step_tl":"Hugasan ang bigas, i-marinate sa mantika at asin."},{"zone":"B","step_zh":"将高品质原切牛肉/瘦猪颈肉切成细小薄丁，用5ml料酒和3g生粉稍加腌制去腥。","step_en":"Slice 高品质原切牛肉/瘦猪颈肉 into thin shreds, marinate with cooking wine and cornstarch.","step_tl":"Hiwain ang 高品质原切牛肉/瘦猪颈肉 nang manipis, i-marinate."},{"zone":"C","step_zh":"将四季时鲜杂蔬拼盘洗净切丝备用，准备好极细的生姜丝。","step_en":"Wash and slice 四季时鲜杂蔬拼盘 into shreds, prepare ginger shreds.","step_tl":"Hugasan at hiwain ang 四季时鲜杂蔬拼盘, ihanda ang luya."}]}'::jsonb, '{"steps":[{"step_zh":"[大火/High Heat] 锅中加入足量清水烧开（米与水的比例建议1:10），倒入腌制好的大米","time_seconds":600},{"step_zh":"[小火/Low Heat] 大火煮沸后盖盖留缝，转小火慢熬40分钟，期间多次顺同一方向搅拌防粘","time_seconds":2400},{"step_zh":"[中火/Medium Heat] 粥底变得浓稠软烂后，转中火，撒入姜丝和高品质原切牛肉/瘦猪颈肉迅速拨散煮2分钟至熟","time_seconds":120},{"step_zh":"[中火/Medium Heat] 最后放入起鲜的四季时鲜杂蔬拼盘，加3g盐和1g白胡椒粉调味，滚煮半分钟极速盛出","time_seconds":30}]}'::jsonb);
